window.SEARCH_INDEX=[{"n": "龙飞凤舞", "p": "lóng fēi fèng wǔ", "m": "原形容山势的蜿蜒雄壮，后也形容书法笔势有力，灵活舒展。", "u": "idiom/longfeifengwu.html"}, {"n": "龙腾虎跃", "p": "lóng téng hǔ yuè", "m": "像龙在飞腾，虎在跳跃。形容跑跳时动作矫健有力。也比喻奋起行动，有所作为。", "u": "idiom/longtenghuyue.html"}, {"n": "虎头蛇尾", "p": "hǔ tóu shé wěi", "m": "头大如虎，尾细如蛇。比喻开始时声势很大，到后来劲头很小，有始无终。", "u": "idiom/hutoushewei.html"}, {"n": "虎背熊腰", "p": "hǔ bèi xióng yāo", "m": "背宽厚如虎，腰粗壮如熊。形容人身体魁梧健壮。", "u": "idiom/hubeixiongyao.html"}, {"n": "虎视眈眈", "p": "hǔ shì dān dān", "m": "像老虎那样凶狠地盯着。形容心怀不善，伺机攫取。", "u": "idiom/hushidandan.html"}, {"n": "虎口拔牙", "p": "hǔ kǒu bá yá", "m": "从老虎嘴里拔牙。比喻做十分危险的事情。", "u": "idiom/hukoubaya.html"}, {"n": "虎口余生", "p": "hǔ kǒu yú shēng", "m": "从老虎嘴里逃出或保存下来的生命。比喻逃脱极危险的境地侥幸活下来。", "u": "idiom/hukouyusheng.html"}, {"n": "如虎添翼", "p": "rú hǔ tiān yì", "m": "好像老虎长上了翅膀。比喻强有力的人得到帮助变得更加强大。", "u": "idiom/ruhutianyi.html"}, {"n": "狼吞虎咽", "p": "láng tūn hǔ yàn", "m": "形容吃东西又猛又急的样子。", "u": "idiom/langtunhuyan.html"}, {"n": "骑虎难下", "p": "qí hǔ nán xià", "m": "骑在老虎背上不能下来。比喻做一件事情进行下去有困难，但情况又不允许中途停止，陷于", "u": "idiom/qihunanxia.html"}, {"n": "调虎离山", "p": "diào hǔ lí shān", "m": "设法使老虎离开原来的山冈。比喻用计使对方离开原来的地方，以便乘机行事。", "u": "idiom/diaohulishan.html"}, {"n": "放虎归山", "p": "fàng hǔ guī shān", "m": "把老虎放回山去。比喻把坏人放回老巢，留下祸根。", "u": "idiom/fanghuguishan.html"}, {"n": "狐假虎威", "p": "hú jiǎ hǔ wēi", "m": "狐狸假借老虎的威势。比喻依仗别人的势力欺压人。", "u": "idiom/hujiahuwei.html"}, {"n": "狼狈为奸", "p": "láng bèi wéi jiān", "m": "狼和狈一同出外伤害牲畜。比喻互相勾结干坏事。", "u": "idiom/langbeiweijian.html"}, {"n": "狼心狗肺", "p": "láng xīn gǒu fèi", "m": "形容心肠像狼和狗一样凶恶狠毒，忘恩负义。", "u": "idiom/langxingoufei.html"}, {"n": "引狼入室", "p": "yǐn láng rù shì", "m": "把狼招引到室内。比喻把坏人或敌人引入内部。", "u": "idiom/yinlangrushi.html"}, {"n": "声名狼藉", "p": "shēng míng láng jí", "m": "形容声望和名誉败坏到极点，不可收拾。", "u": "idiom/shengminglangji.html"}, {"n": "杯盘狼藉", "p": "bēi pán láng jí", "m": "杯子盘子乱七八糟地放着。形容吃喝以后桌面杂乱的样子。", "u": "idiom/beipanlangji.html"}, {"n": "豺狼当道", "p": "chái láng dāng dào", "m": "豺狼横在道路中间。比喻坏人当权。", "u": "idiom/chailangdangdao.html"}, {"n": "如狼似虎", "p": "rú láng sì hǔ", "m": "像狼和虎一样凶狠。比喻非常凶暴残忍，也形容勇猛有劲。", "u": "idiom/rulangsihu.html"}, {"n": "马到成功", "p": "mǎ dào chéng gōng", "m": "形容工作刚开始就取得成功。", "u": "idiom/madaochenggong.html"}, {"n": "马不停蹄", "p": "mǎ bù tíng tí", "m": "比喻不停顿地向前走，连续不断地进行。", "u": "idiom/mabutingti.html"}, {"n": "老马识途", "p": "lǎo mǎ shí tú", "m": "老马认识路。比喻有经验的人对事情比较熟悉，能起到引导作用。", "u": "idiom/laomashitu.html"}, {"n": "汗马功劳", "p": "hàn mǎ gōng láo", "m": "在战场上建立战功。现指辛勤工作做出的贡献。", "u": "idiom/hanmagonglao.html"}, {"n": "牛刀小试", "p": "niú dāo xiǎo shì", "m": "比喻有大本领的人，先在小事情上略展才能。也比喻有能力的人刚开始工作就表现出才干。", "u": "idiom/niudaoxiaoshi.html"}, {"n": "对牛弹琴", "p": "duì niú tán qín", "m": "讥笑听话的人不懂对方说的是什么。也讥笑说话的人不看对象。", "u": "idiom/duiniutanqin.html"}, {"n": "汗牛充栋", "p": "hàn niú chōng dòng", "m": "书运输时牛累得出汗，存放时可堆至屋顶。形容藏书非常多。", "u": "idiom/hanniuchongdong.html"}, {"n": "庖丁解牛", "p": "páo dīng jiě niú", "m": "比喻经过反复实践，掌握了事物的客观规律，做事得心应手，运用自如。", "u": "idiom/paodingjieniu.html"}, {"n": "牛鬼蛇神", "p": "niú guǐ shé shén", "m": "原形容虚幻怪诞。后比喻社会上形形色色的坏人。", "u": "idiom/niuguisheshen.html"}, {"n": "泥牛入海", "p": "ní niú rù hǎi", "m": "泥塑的牛掉到海里。比喻一去不再回来，杳无音信。", "u": "idiom/niniuruhai.html"}, {"n": "羊入虎口", "p": "yáng rù hǔ kǒu", "m": "比喻置身于危险的境地，必死无疑。", "u": "idiom/yangruhukou.html"}, {"n": "亡羊补牢", "p": "wáng yáng bǔ láo", "m": "羊逃跑了再去修补羊圈，还不算晚。比喻出了问题以后想办法补救，可以防止继续受损失。", "u": "idiom/wangyangbulao.html"}, {"n": "顺手牵羊", "p": "shùn shǒu qiān yáng", "m": "顺手把人家的羊牵走。比喻趁势将敌手捉住或乘机利用别人。现比喻乘机拿走别人的东西。", "u": "idiom/shunshouqianyang.html"}, {"n": "鸡鸣狗盗", "p": "jī míng gǒu dào", "m": "指微不足道的本领。也指偷偷摸摸的行为。", "u": "idiom/jiminggoudao.html"}, {"n": "鸡犬不宁", "p": "jī quǎn bù níng", "m": "形容骚扰得厉害，连鸡狗都不得安宁。", "u": "idiom/jiquanbuning.html"}, {"n": "鸡飞狗跳", "p": "jī fēi gǒu tiào", "m": "把鸡吓得飞起来，把狗吓得到处乱跳。形容惊慌得乱成一团。", "u": "idiom/jifeigoutiao.html"}, {"n": "杀鸡取卵", "p": "shā jī qǔ luǎn", "m": "为了要得到鸡蛋，不惜把鸡杀了。比喻贪图眼前的好处而不顾长远利益。", "u": "idiom/shajiquluan.html"}, {"n": "鹤立鸡群", "p": "hè lì jī qún", "m": "像鹤站在鸡群中一样。比喻一个人的仪表或才能在周围一群人里显得很突出。", "u": "idiom/helijiqun.html"}, {"n": "呆若木鸡", "p": "dāi ruò mù jī", "m": "呆得像木头鸡一样。形容因恐惧或惊异而发愣的样子。", "u": "idiom/dairuomuji.html"}, {"n": "偷鸡摸狗", "p": "tōu jī mō gǒu", "m": "指偷窃的行为。也指不正经的勾当。", "u": "idiom/toujimogou.html"}, {"n": "狗急跳墙", "p": "gǒu jí tiào qiáng", "m": "狗急了也能跳过墙去。比喻坏人在走投无路时豁出去，不顾一切地捣乱。", "u": "idiom/goujitiaoqiang.html"}, {"n": "蝇营狗苟", "p": "yíng yíng gǒu gǒu", "m": "像苍蝇那样飞来飞去，像狗那样苟且偷生。形容人不顾廉耻，到处钻营。", "u": "idiom/yingyinggougou.html"}, {"n": "白云苍狗", "p": "bái yún cāng gǒu", "m": "浮云像白衣裳，顷刻又变得像苍狗。比喻事物变化不定，世事无常。", "u": "idiom/baiyuncanggou.html"}, {"n": "兔死狗烹", "p": "tù sǐ gǒu pēng", "m": "兔子死了，猎狗就被人烹食。比喻给统治者效劳的人事成后被抛弃或杀掉。", "u": "idiom/tusigoupeng.html"}, {"n": "狡兔三窟", "p": "jiǎo tù sān kū", "m": "狡猾的兔子准备好几个藏身的窝。比喻隐蔽的地方或方法多，善于为自己留后路。", "u": "idiom/jiaotusanku.html"}, {"n": "守株待兔", "p": "shǒu zhū dài tù", "m": "原比喻希图不经过努力而得到成功的侥幸心理。现也比喻死守狭隘经验，不知变通。", "u": "idiom/shouzhudaitu.html"}, {"n": "乌飞兔走", "p": "wū fēi tù zǒu", "m": "指日月运行。形容光阴迅速流逝。", "u": "idiom/wufeituzou.html"}, {"n": "鸟语花香", "p": "niǎo yǔ huā xiāng", "m": "鸟叫得好听，花开得喷香。形容春天的美好景象。", "u": "idiom/niaoyuhuaxiang.html"}, {"n": "百鸟朝凤", "p": "bǎi niǎo cháo fèng", "m": "旧时喻指君主圣明而天下依附，后也比喻德高望重者众望所归。", "u": "idiom/bainiaochaofeng.html"}, {"n": "惊弓之鸟", "p": "jīng gōng zhī niǎo", "m": "被弓箭吓怕了的鸟。比喻受过惊吓，遇到一点动静就非常害怕的人。", "u": "idiom/jinggongzhiniao.html"}, {"n": "一石二鸟", "p": "yī shí èr niǎo", "m": "扔一块石头打中两只鸟。比喻一个举动同时达到两个目的。", "u": "idiom/yishierniao.html"}, {"n": "笨鸟先飞", "p": "bèn niǎo xiān fēi", "m": "行动笨拙的鸟要先飞。比喻能力差的人怕落后，做事比别人先动手。多用作谦辞。", "u": "idiom/benniaoxianfei.html"}, {"n": "莺歌燕舞", "p": "yīng gē yàn wǔ", "m": "黄莺在歌唱，小燕子在飞舞。形容春天鸟儿喧闹活跃的景象。现常比喻革命和建设蓬勃兴旺", "u": "idiom/yinggeyanwu.html"}, {"n": "莺声燕语", "p": "yīng shēng yàn yǔ", "m": "原形容大好春光。后多形容年轻女子说笑的声音，清脆悦耳。", "u": "idiom/yingshengyanyu.html"}, {"n": "鱼龙混杂", "p": "yú lóng hùn zá", "m": "比喻坏人和好人混在一起。", "u": "idiom/yulonghunza.html"}, {"n": "鱼目混珠", "p": "yú mù hùn zhū", "m": "拿鱼眼睛冒充珍珠。比喻用假的冒充真的。", "u": "idiom/yumuhunzhu.html"}, {"n": "如鱼得水", "p": "rú yú dé shuǐ", "m": "好像鱼得到水一样。比喻有所凭借，也比喻得到跟自己十分投合的人或对自己很合适的环境", "u": "idiom/ruyudeshui.html"}, {"n": "沉鱼落雁", "p": "chén yú luò yàn", "m": "鱼见之沉入水底，雁见之降落沙洲。形容女子容貌美丽。", "u": "idiom/chenyuluoyan.html"}, {"n": "缘木求鱼", "p": "yuán mù qiú yú", "m": "爬到树上去找鱼。比喻方向或办法不对头，不可能达到目的。", "u": "idiom/yuanmuqiuyu.html"}, {"n": "井底之蛙", "p": "jǐng dǐ zhī wā", "m": "井底的青蛙只能看到井口那么大的一块天。比喻见识狭窄的人。", "u": "idiom/jingdizhiwa.html"}, {"n": "鹬蚌相争", "p": "yù bàng xiāng zhēng", "m": "比喻双方相持不下，而使第三者从中得利。常与「渔翁得利」连用。", "u": "idiom/yubangxiangzheng.html"}, {"n": "螳螂捕蝉", "p": "táng láng bǔ chán", "m": "螳螂正要捉蝉，不知黄雀在它后面正要吃它。比喻目光短浅，只想到算计别人，没想到别人", "u": "idiom/tanglangbuchan.html"}, {"n": "螳臂当车", "p": "táng bì dāng chē", "m": "螳螂举起前肢企图阻挡车子前进。比喻做力量做不到的事情，必然失败。", "u": "idiom/tangbidangche.html"}, {"n": "飞蛾扑火", "p": "fēi é pū huǒ", "m": "飞蛾扑到火上。比喻自取灭亡，也比喻不顾一切地追求。", "u": "idiom/feiepuhuo.html"}, {"n": "蚍蜉撼树", "p": "pí fú hàn shù", "m": "蚂蚁想摇动大树。比喻自不量力。", "u": "idiom/pifuhanshu.html"}, {"n": "光明磊落", "p": "guāng míng lěi luò", "m": "胸怀坦白，正大光明。", "u": "idiom/guangmingleiluo.html"}, {"n": "堂堂正正", "p": "táng táng zhèng zhèng", "m": "形容言行光明正大，也形容身材威武、仪表堂堂。", "u": "idiom/tangtangzhengzheng.html"}, {"n": "忠心耿耿", "p": "zhōng xīn gěng gěng", "m": "形容非常忠诚。", "u": "idiom/zhongxingenggeng.html"}, {"n": "大义凛然", "p": "dà yì lǐn rán", "m": "由于胸怀正义而神态庄严，令人敬畏。", "u": "idiom/dayilinran.html"}, {"n": "铁面无私", "p": "tiě miàn wú sī", "m": "形容公正严明，不怕权势，不讲情面。", "u": "idiom/tiemianwusi.html"}, {"n": "刚正不阿", "p": "gāng zhèng bù ē", "m": "刚强正直，不逢迎，无偏私。", "u": "idiom/gangzhengbue.html"}, {"n": "克己奉公", "p": "kè jǐ fèng gōng", "m": "克制自己的私心，一心为公。", "u": "idiom/kejifenggong.html"}, {"n": "奉公守法", "p": "fèng gōng shǒu fǎ", "m": "奉行公事，遵守法令。形容办事守规矩。", "u": "idiom/fenggongshoufa.html"}, {"n": "廉洁奉公", "p": "lián jié fèng gōng", "m": "廉直不贪，忠诚履行公职。", "u": "idiom/lianjiefenggong.html"}, {"n": "见利思义", "p": "jiàn lì sī yì", "m": "看到货财，要想到道义。指面对利益先考虑是否符合道义。", "u": "idiom/jianlisiyi.html"}, {"n": "拾金不昧", "p": "shí jīn bù mèi", "m": "拾到东西并不隐瞒下来据为己有。指不占小便宜，良好的道德风尚。", "u": "idiom/shijinbumei.html"}, {"n": "助人为乐", "p": "zhù rén wéi lè", "m": "把帮助别人作为自己的快乐。", "u": "idiom/zhurenweile.html"}, {"n": "舍己为人", "p": "shě jǐ wèi rén", "m": "舍弃自己的利益去帮助别人。", "u": "idiom/shejiweiren.html"}, {"n": "大公无私", "p": "dà gōng wú sī", "m": "指办事公正，没有私心。现多指从集体利益出发，毫无个人打算。", "u": "idiom/dagongwusi.html"}, {"n": "公而忘私", "p": "gōng ér wàng sī", "m": "为了公事而不考虑私事，为了集体利益而不考虑个人得失。", "u": "idiom/gongerwangsi.html"}, {"n": "鞠躬尽瘁", "p": "jū gōng jìn cuì", "m": "指恭敬谨慎，竭尽心力。常与「死而后已」连用。", "u": "idiom/jugongjincui.html"}, {"n": "死而后已", "p": "sǐ ér hòu yǐ", "m": "到死才停止。形容为完成一种责任而奋斗终身。", "u": "idiom/sierhouyi.html"}, {"n": "先人后己", "p": "xiān rén hòu jǐ", "m": "首先考虑别人，然后想到自己。", "u": "idiom/xianrenhouji.html"}, {"n": "雪中送炭", "p": "xuě zhōng sòng tàn", "m": "在下雪天给人送炭取暖。比喻在别人急需时给以物质上或精神上的帮助。", "u": "idiom/xuezhongsongtan.html"}, {"n": "扶老携幼", "p": "fú lǎo xié yòu", "m": "搀着老人，领着小孩。形容人们成群结队而行，也形容照顾老幼的美德。", "u": "idiom/fulaoxieyou.html"}, {"n": "扶贫济困", "p": "fú pín jì kùn", "m": "扶持贫穷的人，接济困难的人。", "u": "idiom/fupinjikun.html"}, {"n": "慷慨解囊", "p": "kāng kǎi jiě náng", "m": "形容极其大方地在经济上帮助别人。", "u": "idiom/kangkaijienang.html"}, {"n": "见义勇为", "p": "jiàn yì yǒng wéi", "m": "看到正义的事，就勇敢地去做。", "u": "idiom/jianyiyongwei.html"}, {"n": "仗义执言", "p": "zhàng yì zhí yán", "m": "为了正义说公道话。指能伸张正义。", "u": "idiom/zhangyizhiyan.html"}, {"n": "挺身而出", "p": "tǐng shēn ér chū", "m": "挺直身体站出来。形容面对着艰难或危险的事情，勇敢地站出来。", "u": "idiom/tingshenerchu.html"}, {"n": "奋不顾身", "p": "fèn bù gù shēn", "m": "奋勇向前，不考虑个人安危。", "u": "idiom/fenbugushen.html"}, {"n": "赴汤蹈火", "p": "fù tāng dǎo huǒ", "m": "沸水敢蹚，烈火敢踏。比喻不避艰险，奋勇向前。", "u": "idiom/futangdaohuo.html"}, {"n": "临危不惧", "p": "lín wēi bù jù", "m": "遇到危难的时候，一点也不怕。", "u": "idiom/linweibuju.html"}, {"n": "视死如归", "p": "shì sǐ rú guī", "m": "把死看得像回家一样平常。形容不怕牺牲生命。", "u": "idiom/shisirugui.html"}, {"n": "悬梁刺股", "p": "xuán liáng cì gǔ", "m": "形容刻苦学习。", "u": "idiom/xuanliangcigu.html"}, {"n": "凿壁偷光", "p": "záo bì tōu guāng", "m": "原指西汉匡衡凿穿墙壁引邻舍之烛光读书。后用来形容家贫而读书刻苦。", "u": "idiom/zaobitouguang.html"}, {"n": "废寝忘食", "p": "fèi qǐn wàng shí", "m": "顾不得睡觉，忘记了吃饭。形容专心努力。", "u": "idiom/feiqinwangshi.html"}, {"n": "手不释卷", "p": "shǒu bù shì juàn", "m": "书本不离手。形容勤奋好学。", "u": "idiom/shoubushijuan.html"}, {"n": "闻鸡起舞", "p": "wén jī qǐ wǔ", "m": "听到鸡叫就起来舞剑。后比喻有志报国的人及时奋起。", "u": "idiom/wenjiqiwu.html"}, {"n": "囊萤映雪", "p": "náng yíng yìng xuě", "m": "原是车胤用口袋装萤火虫来照书本，孙康利用雪的反光勤奋苦学的故事。后形容刻苦攻读。", "u": "idiom/nangyingyingxue.html"}, {"n": "牛角挂书", "p": "niú jiǎo guà shū", "m": "比喻读书勤奋，学习刻苦。", "u": "idiom/niujiaoguashu.html"}, {"n": "韦编三绝", "p": "wéi biān sān jué", "m": "编联竹简的皮绳断了三次。比喻读书勤奋。", "u": "idiom/weibiansanjue.html"}, {"n": "学富五车", "p": "xué fù wǔ chē", "m": "形容读书多，学识丰富。", "u": "idiom/xuefuwuche.html"}, {"n": "才高八斗", "p": "cái gāo bā dǒu", "m": "比喻人极有才华。", "u": "idiom/caigaobadou.html"}, {"n": "满腹经纶", "p": "mǎn fù jīng lún", "m": "形容人极有才干和智谋。", "u": "idiom/manfujinglun.html"}, {"n": "博古通今", "p": "bó gǔ tōng jīn", "m": "对古代的事知道得很多，并且通晓现代的事情。形容知识丰富。", "u": "idiom/bogutongjin.html"}, {"n": "融会贯通", "p": "róng huì guàn tōng", "m": "把各方面的知识和道理融化汇合，得到全面透彻的理解。", "u": "idiom/ronghuiguantong.html"}, {"n": "举一反三", "p": "jǔ yī fǎn sān", "m": "从一件事情类推而知道其他许多事情。比喻善于学习，能够由此及彼。", "u": "idiom/juyifansan.html"}, {"n": "触类旁通", "p": "chù lèi páng tōng", "m": "掌握了某一事物的知识或规律，进而推知同类事物的知识或规律。", "u": "idiom/chuleipangtong.html"}, {"n": "温故知新", "p": "wēn gù zhī xīn", "m": "温习旧的知识，得到新的理解和体会。也指回忆过去，能更好地认识现在。", "u": "idiom/wenguzhixin.html"}, {"n": "循序渐进", "p": "xún xù jiàn jìn", "m": "按照一定的步骤或顺序逐渐深入或提高。", "u": "idiom/xunxujianjin.html"}, {"n": "日积月累", "p": "rì jī yuè lěi", "m": "一天一天地、一月一月地不断积累。指长时间不断地积累。", "u": "idiom/rijiyuelei.html"}, {"n": "积少成多", "p": "jī shǎo chéng duō", "m": "积累少量的东西，能成为巨大的数量。", "u": "idiom/jishaochengduo.html"}, {"n": "聚沙成塔", "p": "jù shā chéng tǎ", "m": "把细沙堆积成宝塔。比喻积少成多。", "u": "idiom/jushachengta.html"}, {"n": "滴水穿石", "p": "dī shuǐ chuān shí", "m": "水不断下滴，可以滴穿石头。比喻只要有恒心，不断努力，事情一定成功。", "u": "idiom/dishuichuanshi.html"}, {"n": "绳锯木断", "p": "shéng jù mù duàn", "m": "用绳当锯子，也能把木头锯断。比喻力量虽小，只要坚持下去，事情就能成功。", "u": "idiom/shengjumuduan.html"}, {"n": "坚持不懈", "p": "jiān chí bù xiè", "m": "坚持到底，一点不松懈。", "u": "idiom/jianchibuxie.html"}, {"n": "锲而不舍", "p": "qiè ér bù shě", "m": "不断地镂刻。比喻有恒心，有毅力。", "u": "idiom/qieerbushe.html"}, {"n": "持之以恒", "p": "chí zhī yǐ héng", "m": "长久坚持下去。", "u": "idiom/chizhiyiheng.html"}, {"n": "孜孜不倦", "p": "zī zī bù juàn", "m": "指工作或学习勤奋不知疲倦。", "u": "idiom/zizibujuan.html"}, {"n": "勤学苦练", "p": "qín xué kǔ liàn", "m": "认真学习，刻苦训练。", "u": "idiom/qinxuekulian.html"}, {"n": "发奋图强", "p": "fā fèn tú qiáng", "m": "下定决心，努力追求进步。", "u": "idiom/fafentuqiang.html"}, {"n": "卧薪尝胆", "p": "wò xīn cháng dǎn", "m": "睡觉睡在柴草上，吃饭睡觉都尝一尝苦胆。形容人刻苦自励，发奋图强。", "u": "idiom/woxinchangdan.html"}, {"n": "磨杵成针", "p": "mó chǔ chéng zhēn", "m": "把铁棒磨成了针。比喻做任何艰难的工作，只要有毅力，下苦功，就能够克服困难，做出成", "u": "idiom/mochuchengzhen.html"}, {"n": "喜出望外", "p": "xǐ chū wàng wài", "m": "遇到意想不到的喜事而感到非常高兴。", "u": "idiom/xichuwangwai.html"}, {"n": "喜上眉梢", "p": "xǐ shàng méi shāo", "m": "喜悦的心情从眉眼上表现出来。", "u": "idiom/xishangmeishao.html"}, {"n": "喜笑颜开", "p": "xǐ xiào yán kāi", "m": "形容心里高兴，满面笑容。", "u": "idiom/xixiaoyankai.html"}, {"n": "喜闻乐见", "p": "xǐ wén lè jiàn", "m": "喜欢听，乐意看。指很受欢迎。", "u": "idiom/xiwenlejian.html"}, {"n": "喜气洋洋", "p": "xǐ qì yáng yáng", "m": "充满了欢喜的神色或气氛。", "u": "idiom/xiqiyangyang.html"}, {"n": "大喜过望", "p": "dà xǐ guò wàng", "m": "结果比原来希望的还好，因而感到特别高兴。", "u": "idiom/daxiguowang.html"}, {"n": "欢天喜地", "p": "huān tiān xǐ dì", "m": "形容非常高兴。", "u": "idiom/huantianxidi.html"}, {"n": "欣喜若狂", "p": "xīn xǐ ruò kuáng", "m": "形容高兴到了极点。", "u": "idiom/xinxiruokuang.html"}, {"n": "眉飞色舞", "p": "méi fēi sè wǔ", "m": "形容人得意兴奋的样子。", "u": "idiom/meifeisewu.html"}, {"n": "眉开眼笑", "p": "méi kāi yǎn xiào", "m": "眉头舒展，眼含笑意。形容高兴愉快的样子。", "u": "idiom/meikaiyanxiao.html"}, {"n": "笑容可掬", "p": "xiào róng kě jū", "m": "形容笑容满面。", "u": "idiom/xiaorongkeju.html"}, {"n": "笑逐颜开", "p": "xiào zhú yán kāi", "m": "笑得使面容舒展开来。形容满脸笑容，十分高兴的样子。", "u": "idiom/xiaozhuyankai.html"}, {"n": "心花怒放", "p": "xīn huā nù fàng", "m": "心里高兴得像花儿盛开一样。形容极其高兴。", "u": "idiom/xinhuanufang.html"}, {"n": "心旷神怡", "p": "xīn kuàng shén yí", "m": "心境开阔，精神愉快。", "u": "idiom/xinkuangshenyi.html"}, {"n": "心满意足", "p": "xīn mǎn yì zú", "m": "形容心中非常满意。", "u": "idiom/xinmanyizu.html"}, {"n": "乐不可支", "p": "lè bù kě zhī", "m": "快乐到不能撑持的地步。形容欣喜到极点。", "u": "idiom/lebukezhi.html"}, {"n": "乐此不疲", "p": "lè cǐ bù pí", "m": "因酷爱干某事而不感觉厌烦。形容对某事特别爱好而沉浸其中。", "u": "idiom/lecibupi.html"}, {"n": "怡然自得", "p": "yí rán zì dé", "m": "形容高兴而满足的样子。", "u": "idiom/yiranzide.html"}, {"n": "悠然自得", "p": "yōu rán zì dé", "m": "形容自由清闲，心情舒畅。", "u": "idiom/youranzide.html"}, {"n": "怒发冲冠", "p": "nù fà chōng guān", "m": "指愤怒得头发直竖，顶着帽子。形容极端愤怒。", "u": "idiom/nufachongguan.html"}, {"n": "怒气冲天", "p": "nù qì chōng tiān", "m": "怒气冲上天空。形容愤怒到极点。", "u": "idiom/nuqichongtian.html"}, {"n": "怒火中烧", "p": "nù huǒ zhōng shāo", "m": "怒火在心中燃烧。形容心中怀着极大的愤怒。", "u": "idiom/nuhuozhongshao.html"}, {"n": "勃然大怒", "p": "bó rán dà nù", "m": "突然变脸大发脾气。", "u": "idiom/borandanu.html"}, {"n": "大发雷霆", "p": "dà fā léi tíng", "m": "比喻大发脾气，大声斥责。", "u": "idiom/dafaleiting.html"}, {"n": "暴跳如雷", "p": "bào tiào rú léi", "m": "急怒叫跳，像打雷一样猛烈。形容又急又怒，大发脾气的样子。", "u": "idiom/baotiaorulei.html"}, {"n": "痛心疾首", "p": "tòng xīn jí shǒu", "m": "形容痛恨到了极点。", "u": "idiom/tongxinjishou.html"}, {"n": "悲痛欲绝", "p": "bēi tòng yù jué", "m": "悲哀伤心到了极点。", "u": "idiom/beitongyujue.html"}, {"n": "痛不欲生", "p": "tòng bù yù shēng", "m": "悲痛得不想活下去。形容悲痛到极点。", "u": "idiom/tongbuyusheng.html"}, {"n": "肝肠寸断", "p": "gān cháng cùn duàn", "m": "肝肠一寸寸断开。比喻伤心到极点。", "u": "idiom/ganchangcunduan.html"}, {"n": "心如刀割", "p": "xīn rú dāo gē", "m": "内心痛苦得像刀割一样。", "u": "idiom/xinrudaoge.html"}, {"n": "万箭穿心", "p": "wàn jiàn chuān xīn", "m": "像万支箭穿透心脏。形容万分伤痛。", "u": "idiom/wanjianchuanxin.html"}, {"n": "痛哭流涕", "p": "tòng kū liú tì", "m": "形容非常伤心地痛哭，眼泪鼻涕一起流。", "u": "idiom/tongkuliuti.html"}, {"n": "泪如雨下", "p": "lèi rú yǔ xià", "m": "眼泪像下雨似的往下掉。形容非常悲痛。", "u": "idiom/leiruyuxia.html"}, {"n": "泣不成声", "p": "qì bù chéng shēng", "m": "哭得噎住了，出不来声音。形容非常伤心。", "u": "idiom/qibuchengsheng.html"}, {"n": "老泪纵横", "p": "lǎo lèi zòng héng", "m": "老人泪流满面，形容极度悲伤或激动。", "u": "idiom/laoleizongheng.html"}, {"n": "老当益壮", "p": "lǎo dāng yì zhuàng", "m": "年纪虽老而志气更旺盛，干劲更足。", "u": "idiom/laodangyizhuang.html"}, {"n": "老骥伏枥", "p": "lǎo jì fú lì", "m": "年老的千里马虽然伏在马槽旁，雄心壮志仍是驰骋千里。比喻有志向的人虽然年老，仍有雄", "u": "idiom/laojifuli.html"}, {"n": "宝刀未老", "p": "bǎo dāo wèi lǎo", "m": "形容人到老年还依然威猛，不减当年。", "u": "idiom/baodaoweilao.html"}, {"n": "初生牛犊", "p": "chū shēng niú dú", "m": "刚生下来的小牛不怕老虎。比喻青年人思想上很少顾虑，敢作敢为。常与「不怕虎」连用。", "u": "idiom/chushengniudu.html"}, {"n": "后生可畏", "p": "hòu shēng kě wèi", "m": "青年人有希望，令人敬畏。指年轻人容易超过老一辈，是可敬畏的。", "u": "idiom/houshengkewei.html"}, {"n": "巾帼英雄", "p": "jīn guó yīng xióng", "m": "指女子中的英雄。", "u": "idiom/jinguoyingxiong.html"}, {"n": "须眉男子", "p": "xū méi nán zǐ", "m": "指男子汉大丈夫，常用来强调男性的气概。", "u": "idiom/xumeinanzi.html"}, {"n": "青梅竹马", "p": "qīng méi zhú mǎ", "m": "形容男女儿童之间两小无猜的情状。", "u": "idiom/qingmeizhuma.html"}, {"n": "总角之交", "p": "zǒng jiǎo zhī jiāo", "m": "童年时期就结交的朋友。", "u": "idiom/zongjiaozhijiao.html"}, {"n": "忘年之交", "p": "wàng nián zhī jiāo", "m": "年辈不相当而结交为友。", "u": "idiom/wangnianzhijiao.html"}, {"n": "莫逆之交", "p": "mò nì zhī jiāo", "m": "指非常要好或情投意合的朋友。", "u": "idiom/monizhijiao.html"}, {"n": "刎颈之交", "p": "wěn jǐng zhī jiāo", "m": "比喻可以同生死、共患难的朋友。", "u": "idiom/wenjingzhijiao.html"}, {"n": "患难之交", "p": "huàn nàn zhī jiāo", "m": "在一起经历过艰难困苦的朋友。", "u": "idiom/huannanzhijiao.html"}, {"n": "酒肉朋友", "p": "jiǔ ròu péng yǒu", "m": "在一起只是吃喝玩乐而不干正经事的朋友。", "u": "idiom/jiuroupengyou.html"}, {"n": "狐朋狗友", "p": "hú péng gǒu yǒu", "m": "泛指一些吃喝玩乐、不务正业的朋友。", "u": "idiom/hupenggouyou.html"}, {"n": "良师益友", "p": "liáng shī yì yǒu", "m": "使人得到教益和帮助的好老师和好朋友。", "u": "idiom/liangshiyiyou.html"}, {"n": "一表人才", "p": "yī biǎo rén cái", "m": "形容人容貌俊秀端正，风度潇洒。", "u": "idiom/yibiaorencai.html"}, {"n": "仪表堂堂", "p": "yí biǎo táng táng", "m": "形容人的外表端正，举止大方，姿态威严。", "u": "idiom/yibiaotangtang.html"}, {"n": "风度翩翩", "p": "fēng dù piān piān", "m": "形容举止洒脱，气质不凡。", "u": "idiom/fengdupianpian.html"}, {"n": "才华横溢", "p": "cái huá héng yì", "m": "多指文学艺术方面而言，很有才华。", "u": "idiom/caihuahengyi.html"}, {"n": "风华正茂", "p": "fēng huá zhèng mào", "m": "正是青春焕发、风采动人和才华横溢的时候。形容青年朝气蓬勃、奋发有为的精神面貌。", "u": "idiom/fenghuazhengmao.html"}, {"n": "眉清目秀", "p": "méi qīng mù xiù", "m": "形容人容貌清秀不俗气。", "u": "idiom/meiqingmuxiu.html"}, {"n": "浓眉大眼", "p": "nóng méi dà yǎn", "m": "又黑又密的眉毛，大大的眼睛。形容眉目有神的人。", "u": "idiom/nongmeidayan.html"}, {"n": "炯炯有神", "p": "jiǒng jiǒng yǒu shén", "m": "形容人的眼睛发亮，很有精神。", "u": "idiom/jiongjiongyoushen.html"}, {"n": "神采奕奕", "p": "shén cǎi yì yì", "m": "形容精神饱满，容光焕发。", "u": "idiom/shencaiyiyi.html"}, {"n": "容光焕发", "p": "róng guāng huàn fā", "m": "形容身体好，精神饱满。", "u": "idiom/rongguanghuanfa.html"}, {"n": "垂头丧气", "p": "chuí tóu sàng qì", "m": "形容因失败或不顺利而情绪低落、萎靡不振的样子。", "u": "idiom/chuitousangqi.html"}, {"n": "无精打采", "p": "wú jīng dǎ cǎi", "m": "形容精神不振，提不起劲头。", "u": "idiom/wujingdacai.html"}, {"n": "蓬头垢面", "p": "péng tóu gòu miàn", "m": "头发蓬乱，脸上很脏。形容生活条件很坏或没有修饰。", "u": "idiom/pengtougoumian.html"}, {"n": "风风火火", "p": "fēng fēng huǒ huǒ", "m": "形容急急忙忙、冒冒失失的样子，也形容很活跃、有劲头的样子。", "u": "idiom/fengfenghuohuo.html"}, {"n": "雷厉风行", "p": "léi lì fēng xíng", "m": "像雷那样猛烈，像风那样快。比喻执行政策法令严厉迅速，也形容办事声势猛烈，行动迅速", "u": "idiom/leilifengxing.html"}, {"n": "细嚼慢咽", "p": "xì jiáo màn yàn", "m": "慢慢地吃东西。引申为慢慢去体味，也指读书学习要仔细品味。", "u": "idiom/xijiaomanyan.html"}, {"n": "囫囵吞枣", "p": "hú lún tūn zǎo", "m": "把枣整个咽下去，不加咀嚼，不辨滋味。比喻对事物不加分析思考，笼统地接受。", "u": "idiom/huluntunzao.html"}, {"n": "走马观花", "p": "zǒu mǎ guān huā", "m": "骑在奔跑的马上看花。原形容事情如意，心境愉快。后多指大略地观察一下，不深入细致。", "u": "idiom/zoumaguanhua.html"}, {"n": "咬牙切齿", "p": "yǎo yá qiè chǐ", "m": "形容极端仇视或痛恨，也形容把某种情绪或感觉竭力抑制住。", "u": "idiom/yaoyaqiechi.html"}, {"n": "指手画脚", "p": "zhǐ shǒu huà jiǎo", "m": "指说话时做出各种动作。形容说话时放肆或得意忘形。", "u": "idiom/zhishouhuajiao.html"}, {"n": "交头接耳", "p": "jiāo tóu jiē ěr", "m": "形容两个人凑近低声交谈。", "u": "idiom/jiaotoujieer.html"}, {"n": "窃窃私语", "p": "qiè qiè sī yǔ", "m": "背地里小声说话。", "u": "idiom/qieqiesiyu.html"}, {"n": "声泪俱下", "p": "shēng lèi jù xià", "m": "一边说一边哭。形容极其悲恸。", "u": "idiom/shengleijuxia.html"}, {"n": "声情并茂", "p": "shēng qíng bìng mào", "m": "指演唱的音色、唱腔和表达的感情都很动人。", "u": "idiom/shengqingbingmao.html"}, {"n": "绘声绘色", "p": "huì shēng huì sè", "m": "把人物的声音、神色都描绘出来了。形容叙述或描写生动逼真。", "u": "idiom/huishenghuise.html"}, {"n": "栩栩如生", "p": "xǔ xǔ rú shēng", "m": "指艺术形象非常逼真，如同活的一样。", "u": "idiom/xuxurusheng.html"}, {"n": "惟妙惟肖", "p": "wéi miào wéi xiào", "m": "描写或模仿得非常逼真。", "u": "idiom/weimiaoweixiao.html"}, {"n": "锦上添花", "p": "jǐn shàng tiān huā", "m": "在锦上再绣花。比喻好上加好，美上添美。", "u": "idiom/jinshangtianhua.html"}, {"n": "同甘共苦", "p": "tóng gān gòng kǔ", "m": "共同享受幸福，共同担当艰苦。", "u": "idiom/tonggangongku.html"}, {"n": "患难与共", "p": "huàn nàn yǔ gòng", "m": "共同承担危险和困难。指彼此关系密切，利害一致。", "u": "idiom/huannanyugong.html"}, {"n": "推心置腹", "p": "tuī xīn zhì fù", "m": "把赤诚的心交给人家。比喻真心待人。", "u": "idiom/tuixinzhifu.html"}, {"n": "肝胆相照", "p": "gān dǎn xiāng zhào", "m": "比喻真心诚意、以真心相见、互相坦诚交往共事。", "u": "idiom/gandanxiangzhao.html"}, {"n": "志同道合", "p": "zhì tóng dào hé", "m": "志向相同，道路一致。形容彼此理想、志趣相合。", "u": "idiom/zhitongdaohe.html"}, {"n": "情同手足", "p": "qíng tóng shǒu zú", "m": "交情很深，如同兄弟一样。", "u": "idiom/qingtongshouzu.html"}, {"n": "两肋插刀", "p": "liǎng lèi chā dāo", "m": "两边肋骨插上刀，表示不怕死。比喻承担极大的牺牲。", "u": "idiom/liangleichadao.html"}, {"n": "形影不离", "p": "xíng yǐng bù lí", "m": "像形体和它的影子那样分不开。形容彼此关系亲密，经常在一起。", "u": "idiom/xingyingbuli.html"}, {"n": "白头偕老", "p": "bái tóu xié lǎo", "m": "夫妻共同生活到老。", "u": "idiom/baitouxielao.html"}, {"n": "相濡以沫", "p": "xiāng rú yǐ mò", "m": "泉水干了，鱼吐沫互相润湿。比喻一同在困难的处境里，用微薄的力量互相帮助。", "u": "idiom/xiangruyimo.html"}, {"n": "举案齐眉", "p": "jǔ àn qí méi", "m": "送饭时把托盘举得跟眉毛一样高。后形容夫妻互相尊敬、十分恩爱。", "u": "idiom/juanqimei.html"}, {"n": "相敬如宾", "p": "xiāng jìng rú bīn", "m": "形容夫妻互相尊敬，像对待宾客一样。", "u": "idiom/xiangjingrubin.html"}, {"n": "一见钟情", "p": "yī jiàn zhōng qíng", "m": "一见面就产生了爱情。", "u": "idiom/yijianzhongqing.html"}, {"n": "比翼双飞", "p": "bǐ yì shuāng fēi", "m": "比喻夫妻情投意合，在事业上并肩前进。", "u": "idiom/biyishuangfei.html"}, {"n": "花好月圆", "p": "huā hǎo yuè yuán", "m": "花儿正盛开，月亮正圆满。比喻美好圆满。多用于祝贺人新婚。", "u": "idiom/huahaoyueyuan.html"}, {"n": "天作之合", "p": "tiān zuò zhī hé", "m": "好像是上天给予安排，很完美地配合到一起。祝人婚姻美满的话。", "u": "idiom/tianzuozhihe.html"}, {"n": "心心相印", "p": "xīn xīn xiāng yìn", "m": "彼此的心意不用说出，就可以互相了解。形容彼此思想感情完全一致。", "u": "idiom/xinxinxiangyin.html"}, {"n": "家庭和睦", "p": "jiā tíng hé mù", "m": "指家庭成员之间相处融洽，没有矛盾。", "u": "idiom/jiatinghemu.html"}, {"n": "其乐融融", "p": "qí lè róng róng", "m": "形容快乐和谐的景象。", "u": "idiom/qilerongrong.html"}, {"n": "天伦之乐", "p": "tiān lún zhī lè", "m": "泛指家庭的乐趣。", "u": "idiom/tianlunzhile.html"}, {"n": "儿孙绕膝", "p": "ér sūn rào xī", "m": "形容子孙围绕在身边，多指老人晚年幸福。", "u": "idiom/ersunraoxi.html"}, {"n": "四世同堂", "p": "sì shì tóng táng", "m": "指祖孙四代共同生活，无一人离世。形容家庭人丁兴旺、和睦美满。", "u": "idiom/sishitongtang.html"}, {"n": "安家立业", "p": "ān jiā lì yè", "m": "安置家庭，创立基业或事业。也指长期在一个地方劳动和生活。", "u": "idiom/anjialiye.html"}, {"n": "安居乐业", "p": "ān jū lè yè", "m": "安定愉快地生活和劳动。", "u": "idiom/anjuleye.html"}, {"n": "兢兢业业", "p": "jīng jīng yè yè", "m": "形容做事谨慎、勤恳、踏实。", "u": "idiom/jingjingyeye.html"}, {"n": "勤勤恳恳", "p": "qín qín kěn kěn", "m": "形容勤劳踏实，也形容勤恳的样子。", "u": "idiom/qinqinkenken.html"}, {"n": "任劳任怨", "p": "rèn láo rèn yuàn", "m": "不怕吃苦，也不怕招怨。", "u": "idiom/renlaorenyuan.html"}, {"n": "埋头苦干", "p": "mái tóu kǔ gàn", "m": "专心一意地刻苦工作。", "u": "idiom/maitoukugan.html"}, {"n": "脚踏实地", "p": "jiǎo tà shí dì", "m": "脚踏在坚实的土地上。比喻做事踏实，认真。", "u": "idiom/jiaotashidi.html"}, {"n": "事必躬亲", "p": "shì bì gōng qīn", "m": "不论什么事一定要亲自去做，亲自过问。", "u": "idiom/shibigongqin.html"}, {"n": "身体力行", "p": "shēn tǐ lì xíng", "m": "亲身体验，努力实行。", "u": "idiom/shentilixing.html"}, {"n": "以身作则", "p": "yǐ shēn zuò zé", "m": "以自己的行动做出榜样。", "u": "idiom/yishenzuoze.html"}, {"n": "事半功倍", "p": "shì bàn gōng bèi", "m": "指做事得法，因而费力小，收效大。", "u": "idiom/shibangongbei.html"}, {"n": "事倍功半", "p": "shì bèi gōng bàn", "m": "指工作费力大，收效小。", "u": "idiom/shibeigongban.html"}, {"n": "游刃有余", "p": "yóu rèn yǒu yú", "m": "刀刃运转于骨节空隙中，在有回旋的余地。比喻工作熟练，有实际经验，解决问题毫不费事", "u": "idiom/yourenyouyu.html"}, {"n": "得心应手", "p": "dé xīn yìng shǒu", "m": "心里怎么想，手就能怎么做。比喻技艺纯熟或做事情非常顺利。", "u": "idiom/dexinyingshou.html"}, {"n": "驾轻就熟", "p": "jià qīng jiù shú", "m": "驾轻车，走熟路。比喻对某事有经验，很熟悉，做起来容易。", "u": "idiom/jiaqingjiushu.html"}, {"n": "东奔西走", "p": "dōng bēn xī zǒu", "m": "到处奔波。多指为生活所迫或为某一目的四处奔走活动。", "u": "idiom/dongbenxizou.html"}, {"n": "南来北往", "p": "nán lái běi wǎng", "m": "有的从南往北，有的从北往南。也泛指来来往往。", "u": "idiom/nanlaibeiwang.html"}, {"n": "东倒西歪", "p": "dōng dǎo xī wāi", "m": "指行走不稳，身不由主。也形容物体倾斜不正。", "u": "idiom/dongdaoxiwai.html"}, {"n": "东张西望", "p": "dōng zhāng xī wàng", "m": "形容这里那里地到处看。", "u": "idiom/dongzhangxiwang.html"}, {"n": "左顾右盼", "p": "zuǒ gù yòu pàn", "m": "向左右两边看。形容人骄傲得意的神情，也形容犹豫观望的样子。", "u": "idiom/zuoguyoupan.html"}, {"n": "南辕北辙", "p": "nán yuán běi zhé", "m": "想往南而车子却向北行。比喻行动和目的正好相反。", "u": "idiom/nanyuanbeizhe.html"}, {"n": "东施效颦", "p": "dōng shī xiào pín", "m": "比喻胡乱模仿，效果极坏。", "u": "idiom/dongshixiaopin.html"}, {"n": "西窗剪烛", "p": "xī chuāng jiǎn zhú", "m": "原指思念远方妻子，盼望相聚夜语。后泛指亲友聚谈。", "u": "idiom/xichuangjianzhu.html"}, {"n": "红白喜事", "p": "hóng bái xǐ shì", "m": "红指结婚做寿，白指丧事，并到一起说就是红白喜事。", "u": "idiom/hongbaixishi.html"}, {"n": "青红皂白", "p": "qīng hóng zào bái", "m": "皂，黑色。青、红、黑、白四色。比喻事情的是非或原因。", "u": "idiom/qinghongzaobai.html"}, {"n": "灯红酒绿", "p": "dēng hóng jiǔ lǜ", "m": "形容奢侈糜烂的生活，也形容都市或娱乐场所的繁华景象。", "u": "idiom/denghongjiulu.html"}, {"n": "姹紫嫣红", "p": "chà zǐ yān hóng", "m": "形容各种花朵娇艳美丽。", "u": "idiom/chaziyanhong.html"}, {"n": "万紫千红", "p": "wàn zǐ qiān hóng", "m": "形容百花齐放，色彩艳丽。也比喻事物丰富多彩。", "u": "idiom/wanziqianhong.html"}, {"n": "金碧辉煌", "p": "jīn bì huī huáng", "m": "形容建筑物装饰华丽，光彩夺目。", "u": "idiom/jinbihuihuang.html"}, {"n": "白发苍苍", "p": "bái fà cāng cāng", "m": "头发灰白。形容人的苍老。", "u": "idiom/baifacangcang.html"}, {"n": "红颜薄命", "p": "hóng yán bó mìng", "m": "旧时指女子容貌美丽但遭遇不幸。", "u": "idiom/hongyanboming.html"}, {"n": "黄粱一梦", "p": "huáng liáng yī mèng", "m": "比喻虚幻不能实现的梦想。", "u": "idiom/huangliangyimeng.html"}, {"n": "青黄不接", "p": "qīng huáng bù jiē", "m": "旧粮已经吃完，新粮尚未接上。也比喻人才或物力前后接不上。", "u": "idiom/qinghuangbujie.html"}, {"n": "黑白分明", "p": "hēi bái fēn míng", "m": "黑色与白色对比鲜明。比喻事非界限很清楚，也形容字迹、画面清楚。", "u": "idiom/heibaifenming.html"}, {"n": "暗无天日", "p": "àn wú tiān rì", "m": "形容在反动势力统治下社会的黑暗。", "u": "idiom/anwutianri.html"}, {"n": "青天白日", "p": "qīng tiān bái rì", "m": "指大白天。也比喻明显的事情或高洁的品德。", "u": "idiom/qingtianbairi.html"}, {"n": "炉火纯青", "p": "lú huǒ chún qīng", "m": "道士炼丹，认为炼到炉里发出纯青色的火焰就算成功了。后用来比喻功夫达到了纯熟完美的", "u": "idiom/luhuochunqing.html"}, {"n": "画饼充饥", "p": "huà bǐng chōng jī", "m": "画个饼来解除饥饿。比喻用空想来安慰自己。", "u": "idiom/huabingchongji.html"}, {"n": "望梅止渴", "p": "wàng méi zhǐ kě", "m": "原意是梅子酸，人想吃梅子就会流涎，因而止渴。后比喻愿望无法实现，用空想安慰自己。", "u": "idiom/wangmeizhike.html"}, {"n": "粗茶淡饭", "p": "cū chá dàn fàn", "m": "形容饮食简单，生活简朴。", "u": "idiom/cuchadanfan.html"}, {"n": "山珍海味", "p": "shān zhēn hǎi wèi", "m": "山野和海里出产的各种珍贵食品。泛指丰富的菜肴。", "u": "idiom/shanzhenhaiwei.html"}, {"n": "茶饭不思", "p": "chá fàn bù sī", "m": "没有心思喝茶吃饭。形容心情焦虑不安，指一个人丢了很重要的东西，连吃饭喝茶的时间都", "u": "idiom/chafanbusi.html"}, {"n": "食不甘味", "p": "shí bù gān wèi", "m": "吃饭都觉得没有味道。形容心里有事，吃东西也不香。", "u": "idiom/shibuganwei.html"}, {"n": "大快朵颐", "p": "dà kuài duǒ yí", "m": "痛痛快快地大吃一顿。", "u": "idiom/dakuaiduoyi.html"}, {"n": "酒足饭饱", "p": "jiǔ zú fàn bǎo", "m": "形容吃饱喝足。", "u": "idiom/jiuzufanbao.html"}, {"n": "饥肠辘辘", "p": "jī cháng lù lù", "m": "肚子饿得咕咕直响。形容十分饥饿。", "u": "idiom/jichanglulu.html"}, {"n": "饥不择食", "p": "jī bù zé shí", "m": "不管什么都吃。比喻需要急迫，顾不得选择。", "u": "idiom/jibuzeshi.html"}, {"n": "津津有味", "p": "jīn jīn yǒu wèi", "m": "指吃得很有味道或谈得很有兴趣。", "u": "idiom/jinjinyouwei.html"}, {"n": "回味无穷", "p": "huí wèi wú qióng", "m": "指吃过东西以后的余味。比喻回想某一事物，越想越觉得有意思。", "u": "idiom/huiweiwuqiong.html"}, {"n": "脍炙人口", "p": "kuài zhì rén kǒu", "m": "切细的烤肉人人都爱吃。比喻好的诗文或事物被众人所称赞。", "u": "idiom/kuaizhirenkou.html"}, {"n": "一鸣惊人", "p": "yī míng jīng rén", "m": "一声鸣叫就使人震惊。比喻平时没有突出的表现，一下子做出惊人的成绩。", "u": "idiom/yimingjingren.html"}, {"n": "一诺千金", "p": "yī nuò qiān jīn", "m": "许下的一个诺言有千金的价值。形容说话算数，极有信用。", "u": "idiom/yinuoqianjin.html"}, {"n": "一箭双雕", "p": "yī jiàn shuāng diāo", "m": "一支箭射中两只雕。比喻做一件事达到两个目的。", "u": "idiom/yijianshuangdiao.html"}, {"n": "一丝不苟", "p": "yī sī bù gǒu", "m": "连最细微的地方也不马虎。形容办事认真，一点儿不敷衍。", "u": "idiom/yisibugou.html"}, {"n": "一视同仁", "p": "yī shì tóng rén", "m": "同样看待，不分亲疏厚薄。形容对人平等相待。", "u": "idiom/yishitongren.html"}, {"n": "一意孤行", "p": "yī yì gū xíng", "m": "指不接受别人的劝告，顽固地按照自己的主观想法去做。", "u": "idiom/yiyiguxing.html"}, {"n": "一蹴而就", "p": "yī cù ér jiù", "m": "踏一步就成功。比喻事情轻而易举，一下子就成功。多用于否定句，指事情不可能轻易完成", "u": "idiom/yicuerjiu.html"}, {"n": "一败涂地", "p": "yī bài tú dì", "m": "形容失败到不可收拾的地步，惨败。", "u": "idiom/yibaitudi.html"}, {"n": "一呼百应", "p": "yī hū bǎi yìng", "m": "一个人呼喊，马上有很多人响应。形容威信高，响应者多。", "u": "idiom/yihubaiying.html"}, {"n": "一往无前", "p": "yī wǎng wú qián", "m": "一直向前，没有什么能阻挡。形容勇猛无畏地前进。", "u": "idiom/yiwangwuqian.html"}, {"n": "一锤定音", "p": "yī chuí dìng yīn", "m": "制造铜锣时最后一锤决定锣的音色。比喻凭一句话或一个行动就把事情决定下来。", "u": "idiom/yichuidingyin.html"}, {"n": "一本正经", "p": "yī běn zhèng jīng", "m": "原指一部合乎道德规范的经典。后形容态度庄重严肃，郑重其事；有时含讽刺意味，指故作", "u": "idiom/yibenzhengjing.html"}, {"n": "一目了然", "p": "yī mù liǎo rán", "m": "看一眼就完全明白。形容事物、事情原委很清晰，一看就知道是怎么回事。", "u": "idiom/yimuliaoran.html"}, {"n": "一举两得", "p": "yī jǔ liǎng dé", "m": "做一件事得到两方面的好处。", "u": "idiom/yijuliangde.html"}, {"n": "一知半解", "p": "yī zhī bàn jiě", "m": "知道得不全面，理解得也不透彻。形容对事物只懂一点皮毛。", "u": "idiom/yizhibanjie.html"}, {"n": "一毛不拔", "p": "yī máo bù bá", "m": "一根汗毛也不肯拔。形容为人非常吝啬自私。", "u": "idiom/yimaobuba.html"}, {"n": "一波三折", "p": "yī bō sān zhé", "m": "原指写字的笔法曲折多变。现比喻文章的结构起伏曲折，也比喻事情进行中意外的变化很多", "u": "idiom/yibosanzhe.html"}, {"n": "一唱一和", "p": "yī chàng yī hè", "m": "一个先唱，一个随声应和。原形容两人感情相通。现多比喻二人互相配合，互相呼应。多含", "u": "idiom/yichangyihe.html"}, {"n": "一筹莫展", "p": "yī chóu mò zhǎn", "m": "一点计策也施展不出，一点办法也想不出来。", "u": "idiom/yichoumozhan.html"}, {"n": "一成不变", "p": "yī chéng bù biàn", "m": "指一经形成，永不改变。形容守旧不变或固守陈规，有时含贬义。", "u": "idiom/yichengbubian.html"}, {"n": "一帆风顺", "p": "yī fān fēng shùn", "m": "船挂着满帆顺风行驶。比喻非常顺利，没有任何阻碍。", "u": "idiom/yifanfengshun.html"}, {"n": "一刀两断", "p": "yī dāo liǎng duàn", "m": "一刀斩为两段。比喻坚决断绝关系，也形容处理事情干脆果断。", "u": "idiom/yidaoliangduan.html"}, {"n": "一得之见", "p": "yī dé zhī jiàn", "m": "指自己对某个问题的一点肤浅见解。多用于自谦。", "u": "idiom/yidezhijian.html"}, {"n": "一分为二", "p": "yī fēn wéi èr", "m": "哲学用语，指事物作为矛盾的统一体，都包含着相互矛盾对立的两个方面。也指看待人或事", "u": "idiom/yifenweier.html"}, {"n": "一干二净", "p": "yī gān èr jìng", "m": "形容十分干净，也指一点儿也不剩，全部消失。", "u": "idiom/yiganerjing.html"}, {"n": "一鼓作气", "p": "yī gǔ zuò qì", "m": "第一次击鼓时士气振作。比喻趁劲头大的时候鼓起干劲，一口气把工作做完。", "u": "idiom/yiguzuoqi.html"}, {"n": "一哄而散", "p": "yī hòng ér sàn", "m": "形容聚在一起的人一下子吵吵嚷嚷地走散了。", "u": "idiom/yihongersan.html"}, {"n": "一挥而就", "p": "yī huī ér jiù", "m": "一动笔就写成了。形容写字、写文章、画画快，才思敏捷。", "u": "idiom/yihuierjiu.html"}, {"n": "一技之长", "p": "yī jì zhī cháng", "m": "指有某种技能或特长。", "u": "idiom/yijizhichang.html"}, {"n": "一见如故", "p": "yī jiàn rú gù", "m": "初次见面就像老朋友一样合得来。", "u": "idiom/yijianrugu.html"}, {"n": "一介不取", "p": "yī jiè bù qǔ", "m": "一点小东西也不拿人家的。形容廉洁、自守。", "u": "idiom/yijiebuqu.html"}, {"n": "一蹶不振", "p": "yī jué bù zhèn", "m": "一跌倒就再也爬不起来。比喻遭受一次挫折以后就再也振作不起来。", "u": "idiom/yijuebuzhen.html"}, {"n": "一刻千金", "p": "yī kè qiān jīn", "m": "一刻时光价值千金。形容时间非常宝贵。", "u": "idiom/yikeqianjin.html"}, {"n": "一劳永逸", "p": "yī láo yǒng yì", "m": "辛苦一次，把事情办好，以后就可以不再费力了。", "u": "idiom/yilaoyongyi.html"}, {"n": "一落千丈", "p": "yī luò qiān zhàng", "m": "原指琴声陡然降落。后用来形容声誉、地位或经济状况急剧下降。", "u": "idiom/yiluoqianzhang.html"}, {"n": "一马当先", "p": "yī mǎ dāng xiān", "m": "原指作战时策马冲锋在前。形容领先，也比喻工作走在群众前面，积极带头。", "u": "idiom/yimadangxian.html"}, {"n": "一马平川", "p": "yī mǎ píng chuān", "m": "能够纵马疾驰的一片广阔平地。指广阔的平原，也比喻前程顺利无阻。", "u": "idiom/yimapingchuan.html"}, {"n": "一念之差", "p": "yī niàn zhī chā", "m": "一个念头的差错。多指因一时错误的想法而造成严重后果。", "u": "idiom/yinianzhicha.html"}, {"n": "一拍即合", "p": "yī pāi jí hé", "m": "一打拍子就合于乐曲的节奏。比喻双方很容易一致，也比喻因情意相投或有利害关系，一下", "u": "idiom/yipaijihe.html"}, {"n": "一盘散沙", "p": "yī pán sǎn shā", "m": "比喻力量分散，没有组织起来，不能形成整体。", "u": "idiom/yipansansha.html"}, {"n": "一贫如洗", "p": "yī pín rú xǐ", "m": "穷得像用水洗过似的，什么都没有。形容十分贫穷。", "u": "idiom/yipinruxi.html"}, {"n": "一曝十寒", "p": "yī pù shí hán", "m": "原意是说，即使是最容易生长的植物，晒一天，冻十天，也不可能生长。比喻学习或工作一", "u": "idiom/yipushihan.html"}, {"n": "一气呵成", "p": "yī qì hē chéng", "m": "一口气做成。形容文章结构紧凑，文气连贯。也比喻做一件事情安排紧凑，迅速不间断地完", "u": "idiom/yiqihecheng.html"}, {"n": "一穷二白", "p": "yī qióng èr bái", "m": "比喻基础差，底子薄。穷，指工农业不发达；白，指文化科学水平不高。", "u": "idiom/yiqiongerbai.html"}, {"n": "一日千里", "p": "yī rì qiān lǐ", "m": "原形容马跑得很快。后比喻进展极快。", "u": "idiom/yiriqianli.html"}, {"n": "一日三秋", "p": "yī rì sān qiū", "m": "一天不见面，就像过了三个季度。比喻分别时间虽短，却觉得很长，形容思念殷切。", "u": "idiom/yirisanqiu.html"}, {"n": "一扫而空", "p": "yī sǎo ér kōng", "m": "一下子便扫除干净。比喻全部清除或消失。", "u": "idiom/yisaoerkong.html"}, {"n": "一身是胆", "p": "yī shēn shì dǎn", "m": "形容胆量大，无所畏惧。", "u": "idiom/yishenshidan.html"}, {"n": "一事无成", "p": "yī shì wú chéng", "m": "连一样事情也没有做成。指什么事情都做不成，形容毫无成就。", "u": "idiom/yishiwucheng.html"}, {"n": "一往情深", "p": "yī wǎng qíng shēn", "m": "指对人或对事物倾注了很深的感情，向往而不能克制。", "u": "idiom/yiwangqingshen.html"}, {"n": "一望无际", "p": "yī wàng wú jì", "m": "一眼望不到边。形容非常辽阔。", "u": "idiom/yiwangwuji.html"}, {"n": "一文不值", "p": "yī wén bù zhí", "m": "指毫无价值。", "u": "idiom/yiwenbuzhi.html"}, {"n": "一无是处", "p": "yī wú shì chù", "m": "没有一点儿对的或好的地方。", "u": "idiom/yiwushichu.html"}, {"n": "一无所获", "p": "yī wú suǒ huò", "m": "什么东西都没有获得。", "u": "idiom/yiwusuohuo.html"}, {"n": "一无所知", "p": "yī wú suǒ zhī", "m": "什么也不知道。", "u": "idiom/yiwusuozhi.html"}, {"n": "一语道破", "p": "yī yǔ dào pò", "m": "一句话就说穿了，说中了要害。", "u": "idiom/yiyudaopo.html"}, {"n": "一针见血", "p": "yī zhēn jiàn xiě", "m": "一针刺下去就见到血。比喻说话直截了当，切中要害。", "u": "idiom/yizhenjianxie.html"}, {"n": "一朝一夕", "p": "yī zhāo yī xī", "m": "一个早晨或一个晚上。形容很短的时间。", "u": "idiom/yizhaoyixi.html"}, {"n": "一枕黄粱", "p": "yī zhěn huáng liáng", "m": "原比喻人生虚幻。后比喻不能实现的梦想。", "u": "idiom/yizhenhuangliang.html"}, {"n": "一字千金", "p": "yī zì qiān jīn", "m": "增损一字，赏予千金。称赞文辞精妙，不可更改。", "u": "idiom/yiziqianjin.html"}, {"n": "两面三刀", "p": "liǎng miàn sān dāo", "m": "比喻居心不良，当面一套，背后一套，玩弄两面手法。", "u": "idiom/liangmiansandao.html"}, {"n": "两全其美", "p": "liǎng quán qí měi", "m": "指做一件事顾全到双方，使两方面都得到好处。", "u": "idiom/liangquanqimei.html"}, {"n": "两小无猜", "p": "liǎng xiǎo wú cāi", "m": "男女小时候在一起玩耍，天真烂漫，没有猜疑。形容幼年男女天真纯洁的友谊。", "u": "idiom/liangxiaowucai.html"}, {"n": "两袖清风", "p": "liǎng xiù qīng fēng", "m": "衣袖中除清风外，别无所有。比喻做官廉洁，也比喻穷得一无所有。", "u": "idiom/liangxiuqingfeng.html"}, {"n": "两虎相争", "p": "liǎng hǔ xiāng zhēng", "m": "两只老虎相互争斗。比喻力量强大的双方相搏斗，必有一伤。", "u": "idiom/lianghuxiangzheng.html"}, {"n": "两败俱伤", "p": "liǎng bài jù shāng", "m": "斗争双方都受到损伤，谁也没得到好处。", "u": "idiom/liangbaijushang.html"}, {"n": "两厢情愿", "p": "liǎng xiāng qíng yuàn", "m": "双方都愿意，互不勉强。也作「一厢情愿」的反义使用。", "u": "idiom/liangxiangqingyuan.html"}, {"n": "三顾茅庐", "p": "sān gù máo lú", "m": "原为汉末刘备三次到隆中拜访诸葛亮的故事。比喻真心诚意，一再邀请、拜访有专长的贤人", "u": "idiom/sangumaolu.html"}, {"n": "三足鼎立", "p": "sān zú dǐng lì", "m": "比喻三方面对立的局势，像鼎的三条腿一样并立。", "u": "idiom/sanzudingli.html"}, {"n": "三生有幸", "p": "sān shēng yǒu xìng", "m": "三世都很幸运。比喻非常幸运，常用作初次见面或得到帮助时的客套话。", "u": "idiom/sanshengyouxing.html"}, {"n": "三心二意", "p": "sān xīn èr yì", "m": "又想这样又想那样，犹豫不定。常指不安心，不专一。", "u": "idiom/sanxineryi.html"}, {"n": "三言两语", "p": "sān yán liǎng yǔ", "m": "很少的几句话。形容说话简短扼要。", "u": "idiom/sanyanliangyu.html"}, {"n": "三位一体", "p": "sān wèi yī tǐ", "m": "原为基督教教义，指圣父、圣子、圣灵合为一位上帝。后泛指三个人、三件事或三个方面联", "u": "idiom/sanweiyiti.html"}, {"n": "三番五次", "p": "sān fān wǔ cì", "m": "形容一再多次，屡次。", "u": "idiom/sanfanwuci.html"}, {"n": "三长两短", "p": "sān cháng liǎng duǎn", "m": "指意外的灾祸或事故，特指人的死亡。多用于忌讳的说法。", "u": "idiom/sanchangliangduan.html"}, {"n": "三令五申", "p": "sān lìng wǔ shēn", "m": "多次命令和告诫。", "u": "idiom/sanlingwushen.html"}, {"n": "三思而行", "p": "sān sī ér xíng", "m": "指经过反复考虑，然后再去做。", "u": "idiom/sansierxing.html"}, {"n": "三头六臂", "p": "sān tóu liù bì", "m": "三个脑袋，六条胳臂。原为佛家语，指佛的法相。后比喻神奇的本领。", "u": "idiom/santouliubi.html"}, {"n": "三更半夜", "p": "sān gēng bàn yè", "m": "指深夜。一夜分为五更，三更是半夜十二时左右。", "u": "idiom/sangengbanye.html"}, {"n": "三教九流", "p": "sān jiào jiǔ liú", "m": "旧指宗教或学术上的各种流派。也指社会上各行各业的人，有时含贬义。", "u": "idiom/sanjiaojiuliu.html"}, {"n": "三缄其口", "p": "sān jiān qí kǒu", "m": "嘴上贴了三道封条。形容说话谨慎，也形容不肯或不敢开口。", "u": "idiom/sanjianqikou.html"}, {"n": "四海为家", "p": "sì hǎi wéi jiā", "m": "原指帝王占有全国。后指什么地方都可以当作自己的家。指志在四方，不留恋家乡或个人小", "u": "idiom/sihaiweijia.html"}, {"n": "四分五裂", "p": "sì fēn wǔ liè", "m": "形容不完整，不集中，不团结，不统一。", "u": "idiom/sifenwulie.html"}, {"n": "四面八方", "p": "sì miàn bā fāng", "m": "指各个方面或各个地方。", "u": "idiom/simianbafang.html"}, {"n": "四面楚歌", "p": "sì miàn chǔ gē", "m": "比喻陷入四面受敌、孤立无援的境地。", "u": "idiom/simianchuge.html"}, {"n": "四通八达", "p": "sì tōng bā dá", "m": "四面八方都有路可通。形容交通极便利，也形容通向各方。", "u": "idiom/sitongbada.html"}, {"n": "四平八稳", "p": "sì píng bā wěn", "m": "原指说话做事稳当。现多形容做事只求不出差错，缺乏积极创新精神。", "u": "idiom/sipingbawen.html"}, {"n": "五光十色", "p": "wǔ guāng shí sè", "m": "形容色彩鲜艳，花样繁多。", "u": "idiom/wuguangshise.html"}, {"n": "五花八门", "p": "wǔ huā bā mén", "m": "原指五行阵和八门阵，是古代两种战术变化很多的阵势。现比喻变化多端或花样繁多。", "u": "idiom/wuhuabamen.html"}, {"n": "五颜六色", "p": "wǔ yán liù sè", "m": "形容色彩复杂或花样繁多。引申为各色各样。", "u": "idiom/wuyanliuse.html"}, {"n": "五体投地", "p": "wǔ tǐ tóu dì", "m": "两手、两膝和头一起着地。是佛教一种最恭敬的行礼仪式。比喻佩服到了极点。", "u": "idiom/wutitoudi.html"}, {"n": "五谷丰登", "p": "wǔ gǔ fēng dēng", "m": "指年成好，粮食丰收。", "u": "idiom/wugufengdeng.html"}, {"n": "五雷轰顶", "p": "wǔ léi hōng dǐng", "m": "比喻遭到了巨大的打击，也形容突然受到强烈的震惊。", "u": "idiom/wuleihongding.html"}, {"n": "五彩缤纷", "p": "wǔ cǎi bīn fēn", "m": "指颜色繁多，非常好看。", "u": "idiom/wucaibinfen.html"}, {"n": "五毒俱全", "p": "wǔ dú jù quán", "m": "原指五种毒性强的动物俱全，比喻各种坏事都做，什么恶习都有。", "u": "idiom/wudujuquan.html"}, {"n": "六神无主", "p": "liù shén wú zhǔ", "m": "形容惊慌着急，没了主意，不知如何才好。", "u": "idiom/liushenwuzhu.html"}, {"n": "六亲不认", "p": "liù qīn bù rèn", "m": "形容不通人情，对亲属都不顾。有时也指对谁都不讲情面，铁面无私。", "u": "idiom/liuqinburen.html"}, {"n": "六根清净", "p": "liù gēn qīng jìng", "m": "佛教用语。六根指眼、耳、鼻、舌、身、意。指断除欲念，没有烦恼。现也泛指不受外界干", "u": "idiom/liugenqingjing.html"}, {"n": "七上八下", "p": "qī shàng bā xià", "m": "形容心里慌乱不安，心神不定。", "u": "idiom/qishangbaxia.html"}, {"n": "七嘴八舌", "p": "qī zuǐ bā shé", "m": "形容人多口杂，议论纷纷。", "u": "idiom/qizuibashe.html"}, {"n": "七手八脚", "p": "qī shǒu bā jiǎo", "m": "形容人多手杂，动作纷乱。", "u": "idiom/qishoubajiao.html"}, {"n": "七零八落", "p": "qī líng bā luò", "m": "形容零散稀疏的样子，特指原来又多又整齐的东西现在零散了。", "u": "idiom/qilingbaluo.html"}, {"n": "七拼八凑", "p": "qī pīn bā còu", "m": "指把零碎的东西拼凑起来。引申为胡乱凑合。", "u": "idiom/qipinbacou.html"}, {"n": "七窍生烟", "p": "qī qiào shēng yān", "m": "形容气愤到极点，好像耳目口鼻都要冒出火来。", "u": "idiom/qiqiaoshengyan.html"}, {"n": "七步成诗", "p": "qī bù chéng shī", "m": "七步之内就能完成一首诗。比喻有才气，文思敏捷。", "u": "idiom/qibuchengshi.html"}, {"n": "八面玲珑", "p": "bā miàn líng lóng", "m": "原指窗户很多，四面八方通明透亮。现形容为人处世圆滑，各方面都能巧妙应对。", "u": "idiom/bamianlinglong.html"}, {"n": "八面威风", "p": "bā miàn wēi fēng", "m": "各个方面都很威风。形容神气十足，声势盛的样子。", "u": "idiom/bamianweifeng.html"}, {"n": "八仙过海", "p": "bā xiān guò hǎi", "m": "相传八仙过海时不用舟船，各有一套法术。后比喻各自拿出本领或办法，互相竞赛。常与「", "u": "idiom/baxianguohai.html"}, {"n": "八拜之交", "p": "bā bài zhī jiāo", "m": "旧时朋友结为兄弟的关系。指结拜的异姓兄弟姐妹。", "u": "idiom/babaizhijiao.html"}, {"n": "九牛一毛", "p": "jiǔ niú yī máo", "m": "九条牛身上的一根毛。比喻极大数量中极微小的数量，微不足道。", "u": "idiom/jiuniuyimao.html"}, {"n": "九死一生", "p": "jiǔ sǐ yī shēng", "m": "形容经历很大危险而幸存。也形容处在生死关头，情况十分危急。", "u": "idiom/jiusiyisheng.html"}, {"n": "九霄云外", "p": "jiǔ xiāo yún wài", "m": "在九重天的外面。比喻无限远的地方或远得无影无踪。", "u": "idiom/jiuxiaoyunwai.html"}, {"n": "九牛二虎", "p": "jiǔ niú èr hǔ", "m": "比喻很大的力气。常用于很费力才做成一件事的场合，常说「费了九牛二虎之力」。", "u": "idiom/jiuniuerhu.html"}, {"n": "十全十美", "p": "shí quán shí měi", "m": "十分完美，毫无欠缺。", "u": "idiom/shiquanshimei.html"}, {"n": "十拿九稳", "p": "shí ná jiǔ wěn", "m": "比喻很有把握，十分可靠。", "u": "idiom/shinajiuwen.html"}, {"n": "十万火急", "p": "shí wàn huǒ jí", "m": "形容事情紧急到了极点。", "u": "idiom/shiwanhuoji.html"}, {"n": "十字路口", "p": "shí zì lù kǒu", "m": "两条道路交叉的地方。比喻处在对重大事情需要决定怎样选择的境地。", "u": "idiom/shizilukou.html"}, {"n": "十室九空", "p": "shí shì jiǔ kōng", "m": "十家有九家一无所有。形容人民大量死亡或逃亡后的荒凉景象。", "u": "idiom/shishijiukong.html"}, {"n": "十指连心", "p": "shí zhǐ lián xīn", "m": "十个指头连着心。表示身体的每个小部分都跟心有不可分的关系。比喻亲人跟自身休戚相关", "u": "idiom/shizhilianxin.html"}, {"n": "百发百中", "p": "bǎi fā bǎi zhòng", "m": "形容射箭或打枪准确，每次都命中目标。也比喻做事有充分把握，绝不落空。", "u": "idiom/baifabaizhong.html"}, {"n": "百折不挠", "p": "bǎi zhé bù náo", "m": "无论受到多少挫折都不退缩。比喻意志坚强，品节刚毅。", "u": "idiom/baizhebunao.html"}, {"n": "百步穿杨", "p": "bǎi bù chuān yáng", "m": "在一百步远以外射中杨柳的叶子。形容箭法或枪法十分高明。", "u": "idiom/baibuchuanyang.html"}, {"n": "百尺竿头", "p": "bǎi chǐ gān tóu", "m": "桅杆或杂技长竿的顶端。比喻极高的官位和功名，或学问、事业有很高的成就。常与「更进", "u": "idiom/baichigantou.html"}, {"n": "百感交集", "p": "bǎi gǎn jiāo jí", "m": "各种感触交织在一起。形容感触很多，心情复杂。", "u": "idiom/baiganjiaoji.html"}, {"n": "百川归海", "p": "bǎi chuān guī hǎi", "m": "许多江河流入大海。比喻大势所趋或众望所归，也比喻许多分散的事物汇集到一个地方。", "u": "idiom/baichuanguihai.html"}, {"n": "百孔千疮", "p": "bǎi kǒng qiān chuāng", "m": "比喻毛病很多，问题严重，已经到了难以收拾的地步。", "u": "idiom/baikongqianchuang.html"}, {"n": "百废待兴", "p": "bǎi fèi dài xīng", "m": "许多被搁置的事情等着要兴办。", "u": "idiom/baifeidaixing.html"}, {"n": "百依百顺", "p": "bǎi yī bǎi shùn", "m": "什么都依从。形容一切都顺从别人。", "u": "idiom/baiyibaishun.html"}, {"n": "百花齐放", "p": "bǎi huā qí fàng", "m": "形容百花盛开，丰富多彩。比喻各种不同形式和风格的艺术自由发展，也形容艺术界的繁荣", "u": "idiom/baihuaqifang.html"}, {"n": "千钧一发", "p": "qiān jūn yī fà", "m": "千钧重量吊在一根头发上。比喻情况万分危急。", "u": "idiom/qianjunyifa.html"}, {"n": "千载难逢", "p": "qiān zǎi nán féng", "m": "一千年里也难碰到一次。形容机会极其难得。", "u": "idiom/qianzainanfeng.html"}, {"n": "千变万化", "p": "qiān biàn wàn huà", "m": "形容变化极多。", "u": "idiom/qianbianwanhua.html"}, {"n": "千军万马", "p": "qiān jūn wàn mǎ", "m": "形容雄壮的队伍或浩大的声势。", "u": "idiom/qianjunwanma.html"}, {"n": "千方百计", "p": "qiān fāng bǎi jì", "m": "想尽或用尽一切办法。", "u": "idiom/qianfangbaiji.html"}, {"n": "千头万绪", "p": "qiān tóu wàn xù", "m": "比喻事情的开端，头绪非常多。也形容事情复杂纷乱。", "u": "idiom/qiantouwanxu.html"}, {"n": "千言万语", "p": "qiān yán wàn yǔ", "m": "形容说的话很多，有说不完的话语。", "u": "idiom/qianyanwanyu.html"}, {"n": "千辛万苦", "p": "qiān xīn wàn kǔ", "m": "各种各样的艰难困苦。", "u": "idiom/qianxinwanku.html"}, {"n": "千山万水", "p": "qiān shān wàn shuǐ", "m": "万道河，千重山。形容路途艰难遥远。", "u": "idiom/qianshanwanshui.html"}, {"n": "千秋万代", "p": "qiān qiū wàn dài", "m": "指世世代代，时间久长。", "u": "idiom/qianqiuwandai.html"}, {"n": "千真万确", "p": "qiān zhēn wàn què", "m": "形容情况非常确实，不容置疑。", "u": "idiom/qianzhenwanque.html"}, {"n": "千里迢迢", "p": "qiān lǐ tiáo tiáo", "m": "形容路途遥远。", "u": "idiom/qianlitiaotiao.html"}, {"n": "千篇一律", "p": "qiān piān yī lǜ", "m": "一千篇文章都一个样。指文章公式化，也比喻办事按一个格式，非常机械。", "u": "idiom/qianpianyilu.html"}, {"n": "万无一失", "p": "wàn wú yī shī", "m": "指非常有把握，绝对不会出差错。", "u": "idiom/wanwuyishi.html"}, {"n": "万众一心", "p": "wàn zhòng yī xīn", "m": "千万人一条心。形容团结一致。", "u": "idiom/wanzhongyixin.html"}, {"n": "万象更新", "p": "wàn xiàng gēng xīn", "m": "一切事物或景象都变得焕然一新。", "u": "idiom/wanxianggengxin.html"}, {"n": "万马奔腾", "p": "wàn mǎ bēn téng", "m": "成千上万匹马在奔跑腾跃。形容群众性的活动声势浩大或场面热烈。", "u": "idiom/wanmabenteng.html"}, {"n": "万古长青", "p": "wàn gǔ cháng qīng", "m": "千秋万代都像松柏一样永远苍翠。比喻崇高的精神或深厚的友谊永远不会消失。", "u": "idiom/wanguchangqing.html"}, {"n": "万事大吉", "p": "wàn shì dà jí", "m": "什么事都很圆满顺利，也指一切事情都已办好。", "u": "idiom/wanshidaji.html"}, {"n": "万水千山", "p": "wàn shuǐ qiān shān", "m": "万道河，千重山。形容路途艰难遥远。", "u": "idiom/wanshuiqianshan.html"}, {"n": "万不得已", "p": "wàn bù dé yǐ", "m": "表示无可奈何，不得不如此。", "u": "idiom/wanbudeyi.html"}, {"n": "纸上谈兵", "p": "zhǐ shàng tán bīng", "m": "在纸面上谈论打仗。比喻空谈理论，不能解决实际问题，也比喻空谈不能成为现实。", "u": "idiom/zhishangtanbing.html"}, {"n": "破釜沉舟", "p": "pò fǔ chén zhōu", "m": "把饭锅打破，把渡船凿沉。比喻不留退路，非打胜仗不可，下决心不顾一切地干到底。", "u": "idiom/pofuchenzhou.html"}, {"n": "草木皆兵", "p": "cǎo mù jiē bīng", "m": "把山上的草木都当做敌兵。形容人在惊慌时疑神疑鬼。", "u": "idiom/caomujiebing.html"}, {"n": "背水一战", "p": "bèi shuǐ yī zhàn", "m": "背后临近河水摆阵。比喻处于绝境之中，为求出路而决一死战。", "u": "idiom/beishuiyizhan.html"}, {"n": "兵不厌诈", "p": "bīng bù yàn zhà", "m": "用兵作战不排斥运用诡变、欺诈的策略或手段克敌制胜。", "u": "idiom/bingbuyanzha.html"}, {"n": "兵贵神速", "p": "bīng guì shén sù", "m": "用兵贵在行动特别迅速。", "u": "idiom/bingguishensu.html"}, {"n": "出奇制胜", "p": "chū qí zhì shèng", "m": "出奇兵战胜敌人。比喻用对方意料不到的方法取得胜利。", "u": "idiom/chuqizhisheng.html"}, {"n": "攻其不备", "p": "gōng qí bù bèi", "m": "趁敌人还没有防备时进攻。", "u": "idiom/gongqibubei.html"}, {"n": "围魏救赵", "p": "wéi wèi jiù zhào", "m": "原指战国时齐军用围攻魏国的方法，迫使魏国撤回攻赵部队而使赵国得救。后指袭击敌人后", "u": "idiom/weiweijiuzhao.html"}, {"n": "声东击西", "p": "shēng dōng jī xī", "m": "指造成要攻打东边的声势，实际上却攻打西边。是使对方产生错觉以出奇制胜的一种战术。", "u": "idiom/shengdongjixi.html"}, {"n": "暗度陈仓", "p": "àn dù chén cāng", "m": "指正面迷惑敌人，而从侧翼进行突然袭击。比喻暗中进行活动。", "u": "idiom/anduchencang.html"}, {"n": "釜底抽薪", "p": "fǔ dǐ chōu xīn", "m": "把柴火从锅底抽掉。比喻从根本上解决问题。", "u": "idiom/fudichouxin.html"}, {"n": "欲擒故纵", "p": "yù qín gù zòng", "m": "故意先放开他，使他放松戒备，充分暴露，然后再把他捉住。", "u": "idiom/yuqinguzong.html"}, {"n": "走为上计", "p": "zǒu wéi shàng jì", "m": "遇到强敌或陷于困境时，以离开回避为最好的策略。", "u": "idiom/zouweishangji.html"}, {"n": "金蝉脱壳", "p": "jīn chán tuō qiào", "m": "蝉变为成虫时要脱去一层壳。比喻用计脱身，使人不能及时发觉。", "u": "idiom/jinchantuoqiao.html"}, {"n": "远交近攻", "p": "yuǎn jiāo jìn gōng", "m": "结交离得远的国家而进攻邻近的国家。这是秦国用以并吞六国、统一全国的外交策略。", "u": "idiom/yuanjiaojingong.html"}, {"n": "无中生有", "p": "wú zhōng shēng yǒu", "m": "道家认为，天下万物生于有，有生于无。把没有的说成有。比喻毫无事实，凭空捏造。", "u": "idiom/wuzhongshengyou.html"}, {"n": "借刀杀人", "p": "jiè dāo shā rén", "m": "比喻自己不出面，借别人的手去害人。", "u": "idiom/jiedaosharen.html"}, {"n": "以逸待劳", "p": "yǐ yì dài láo", "m": "指在战争中做好充分准备，养精蓄锐，等疲乏的敌人来犯时给以迎头痛击。", "u": "idiom/yiyidailao.html"}, {"n": "混水摸鱼", "p": "hún shuǐ mō yú", "m": "比喻乘混乱的时候从中捞取利益。", "u": "idiom/hunshuimoyu.html"}, {"n": "隔岸观火", "p": "gé àn guān huǒ", "m": "隔着河看人家着火。比喻对别人的危难不去求助，在一旁看热闹。", "u": "idiom/geanguanhuo.html"}, {"n": "笑里藏刀", "p": "xiào lǐ cáng dāo", "m": "形容对人外表和气，却阴险毒辣。", "u": "idiom/xiaolicangdao.html"}, {"n": "空城计", "p": "kōng chéng jì", "m": "指在危急处境下，掩饰空虚，骗过对方的策略。", "u": "idiom/kongchengji.html"}, {"n": "苦肉计", "p": "kǔ ròu jì", "m": "故意伤害自己的肉体以骗取敌方信任的计策。", "u": "idiom/kurouji.html"}, {"n": "连环计", "p": "lián huán jì", "m": "指一个接一个互相关联的计策。", "u": "idiom/lianhuanji.html"}, {"n": "指桑骂槐", "p": "zhǐ sāng mà huái", "m": "指着桑树骂槐树。比喻表面上骂这个人，实际上是骂那个人。", "u": "idiom/zhisangmahuai.html"}, {"n": "偷梁换柱", "p": "tōu liáng huàn zhù", "m": "比喻暗中玩弄手法，以假代真，以劣代优。", "u": "idiom/toulianghuanzhu.html"}, {"n": "关门捉贼", "p": "guān mén zhuō zéi", "m": "关起门来捉进入屋内的盗贼。比喻将小股敌人包围起来歼灭。", "u": "idiom/guanmenzhuozei.html"}, {"n": "打草惊蛇", "p": "dǎ cǎo jīng shé", "m": "打草惊了草里的蛇。原比喻惩罚了甲而使乙有所警觉。后多比喻做法不谨慎，反使对方有所", "u": "idiom/dacaojingshe.html"}, {"n": "完璧归赵", "p": "wán bì guī zhào", "m": "本指蔺相如将和氏璧完好地自秦送回赵国。后比喻把原物完好地归还本人。", "u": "idiom/wanbiguizhao.html"}, {"n": "负荆请罪", "p": "fù jīng qǐng zuì", "m": "背着荆条向对方请罪。表示向人认错赔罪。", "u": "idiom/fujingqingzui.html"}, {"n": "草船借箭", "p": "cǎo chuán jiè jiàn", "m": "运用智谋，凭借他人的人力或财力来达到自己的目的。", "u": "idiom/caochuanjiejian.html"}, {"n": "指鹿为马", "p": "zhǐ lù wéi mǎ", "m": "指着鹿，说是马。比喻故意颠倒黑白，混淆是非。", "u": "idiom/zhiluweima.html"}, {"n": "图穷匕见", "p": "tú qióng bǐ xiàn", "m": "地图全部展开，露出了匕首。比喻事情发展到最后，真相或本意显露了出来。", "u": "idiom/tuqiongbixian.html"}, {"n": "风声鹤唳", "p": "fēng shēng hè lì", "m": "听到风声和鹤叫声，都疑心是追兵。形容人在惊慌时疑神疑鬼。", "u": "idiom/fengshengheli.html"}, {"n": "约法三章", "p": "yuē fǎ sān zhāng", "m": "原指订立法律与人民相约遵守。后泛指订立简单的条款，以资遵守。", "u": "idiom/yuefasanzhang.html"}, {"n": "退避三舍", "p": "tuì bì sān shè", "m": "主动退让九十里。比喻退让和回避，避免冲突。", "u": "idiom/tuibisanshe.html"}, {"n": "马革裹尸", "p": "mǎ gé guǒ shī", "m": "用马皮把尸体裹起来。指英勇牺牲在战场。", "u": "idiom/mageguoshi.html"}, {"n": "毛遂自荐", "p": "máo suì zì jiàn", "m": "毛遂自我推荐。比喻自告奋勇，自己推荐自己担任某项工作。", "u": "idiom/maosuizijian.html"}, {"n": "假途伐虢", "p": "jiǎ tú fá guó", "m": "泛指用借路的名义而灭亡这个国家。", "u": "idiom/jiatufaguo.html"}, {"n": "胸有成竹", "p": "xiōng yǒu chéng zhú", "m": "画竹子之前心中要先有竹子的形象。比喻在做事之前已经有完整的设想和计划。", "u": "idiom/xiongyouchengzhu.html"}, {"n": "洛阳纸贵", "p": "luò yáng zhǐ guì", "m": "比喻著作有价值，流传广。", "u": "idiom/luoyangzhigui.html"}, {"n": "江郎才尽", "p": "jiāng láng cái jìn", "m": "原指江淹少有文名，晚年诗文无佳句。比喻才情减退，写不出好作品。", "u": "idiom/jianglangcaijin.html"}, {"n": "班门弄斧", "p": "bān mén nòng fǔ", "m": "在鲁班门前舞弄斧子。比喻在行家面前卖弄本领，不自量力。", "u": "idiom/banmennongfu.html"}, {"n": "名落孙山", "p": "míng luò sūn shān", "m": "指考试或选拔没有录取。", "u": "idiom/mingluosunshan.html"}, {"n": "将相和", "p": "jiàng xiàng hé", "m": "比喻文官武将团结一致，共同把国家的事情办好。", "u": "idiom/jiangxianghe.html"}, {"n": "投笔从戎", "p": "tóu bǐ cóng róng", "m": "扔掉笔去参军。指文人从军。", "u": "idiom/toubicongrong.html"}, {"n": "运筹帷幄", "p": "yùn chóu wéi wò", "m": "在军帐内对军略做全面计划。常指在后方决定作战方案，也泛指主持大计，考虑决策。", "u": "idiom/yunchouweiwo.html"}, {"n": "多多益善", "p": "duō duō yì shàn", "m": "越多越好。", "u": "idiom/duoduoyishan.html"}, {"n": "明修栈道", "p": "míng xiū zhàn dào", "m": "比喻用一种假象迷惑对方，实际上却另有打算。常与「暗度陈仓」连用。", "u": "idiom/mingxiuzhandao.html"}, {"n": "项庄舞剑", "p": "xiàng zhuāng wǔ jiàn", "m": "比喻说话和行动的真实意图别有所指。常与「意在沛公」连用。", "u": "idiom/xiangzhuangwujian.html"}, {"n": "破镜重圆", "p": "pò jìng chóng yuán", "m": "比喻夫妻失散或离婚后重新团聚。", "u": "idiom/pojingchongyuan.html"}, {"n": "问鼎中原", "p": "wèn dǐng zhōng yuán", "m": "比喻企图夺取天下，也指在某领域争夺最高地位。", "u": "idiom/wendingzhongyuan.html"}, {"n": "逐鹿中原", "p": "zhú lù zhōng yuán", "m": "指群雄并起，争夺天下。", "u": "idiom/zhuluzhongyuan.html"}, {"n": "四面埋伏", "p": "sì miàn mái fú", "m": "比喻陷入四面受敌、孤立无援的境地。", "u": "idiom/simianmaifu.html"}, {"n": "单刀赴会", "p": "dān dāo fù huì", "m": "原指蜀将关羽只带一口刀和少数随从赴东吴宴会。后泛指一个人冒险赴约，有赞扬赴会者的", "u": "idiom/dandaofuhui.html"}, {"n": "七擒孟获", "p": "qī qín mèng huò", "m": "比喻运用策略，使对方心服口服。", "u": "idiom/qiqinmenghuo.html"}, {"n": "乐不思蜀", "p": "lè bù sī shǔ", "m": "在新环境中得到乐趣，不再想回到原来环境中去。", "u": "idiom/lebusishu.html"}, {"n": "刮目相看", "p": "guā mù xiāng kàn", "m": "指别人已有进步，不能再用老眼光去看他。", "u": "idiom/guamuxiangkan.html"}, {"n": "吴下阿蒙", "p": "wú xià ā méng", "m": "比喻人学识尚浅，没有学问。", "u": "idiom/wuxiaameng.html"}, {"n": "三英战吕布", "p": "sān yīng zhàn lǚ bù", "m": "形容以多对少的激烈战斗，也比喻合力围攻强敌。", "u": "idiom/sanyingzhanlubu.html"}, {"n": "过五关斩六将", "p": "guò wǔ guān zhǎn liù jiàng", "m": "比喻克服重重困难，达成目标。", "u": "idiom/guowuguanzhanliujiang.html"}, {"n": "塞翁失马", "p": "sài wēng shī mǎ", "m": "比喻一时虽然受到损失，也许反而因此能得到好处。也指坏事在一定条件下可变为好事。常", "u": "idiom/saiwengshima.html"}, {"n": "画蛇添足", "p": "huà shé tiān zú", "m": "画蛇时给蛇添上脚。比喻做了多余的事，非但无益，反而不合适。", "u": "idiom/huashetianzu.html"}, {"n": "画龙点睛", "p": "huà lóng diǎn jīng", "m": "原形容梁代画家张僧繇作画的神妙。后多比喻写文章或讲话时，在关键处用几句话点明实质", "u": "idiom/hualongdianjing.html"}, {"n": "刻舟求剑", "p": "kè zhōu qiú jiàn", "m": "比喻不懂事物已发展变化而仍静止地看问题。", "u": "idiom/kezhouqiujian.html"}, {"n": "掩耳盗铃", "p": "yǎn ěr dào líng", "m": "捂住自己的耳朵去偷铃铛。比喻自己欺骗自己，明明掩盖不住的事情偏要想法子掩盖。", "u": "idiom/yanerdaoling.html"}, {"n": "自相矛盾", "p": "zì xiāng máo dùn", "m": "比喻自己说话做事前后抵触。", "u": "idiom/zixiangmaodun.html"}, {"n": "滥竽充数", "p": "làn yú chōng shù", "m": "不会吹竽的人混在吹竽的队伍里充数。比喻无本领的冒充有本领，次货冒充好货。", "u": "idiom/lanyuchongshu.html"}, {"n": "买椟还珠", "p": "mǎi dú huán zhū", "m": "买下木匣，退还了珍珠。比喻没有眼力，取舍不当，次要的东西比主要的还要好。", "u": "idiom/maiduhuanzhu.html"}, {"n": "叶公好龙", "p": "yè gōng hào lóng", "m": "比喻口头上说爱好某事物，实际上并不真爱好。", "u": "idiom/yegonghaolong.html"}, {"n": "拔苗助长", "p": "bá miáo zhù zhǎng", "m": "把苗拔起，以助其生长。比喻违反事物发展的客观规律，急于求成，反而把事情弄糟。", "u": "idiom/bamiaozhuzhang.html"}, {"n": "邯郸学步", "p": "hán dān xué bù", "m": "比喻模仿人不到家，反把原来自己会的东西忘了。", "u": "idiom/handanxuebu.html"}, {"n": "盲人摸象", "p": "máng rén mō xiàng", "m": "比喻对事物只凭片面的了解或局部的经验，就乱加猜测，想做出全面的判断。", "u": "idiom/mangrenmoxiang.html"}, {"n": "杞人忧天", "p": "qǐ rén yōu tiān", "m": "比喻不必要的或缺乏根据的忧虑和担心。", "u": "idiom/qirenyoutian.html"}, {"n": "愚公移山", "p": "yú gōng yí shān", "m": "比喻坚持不懈地改造自然和坚定不移地进行斗争。", "u": "idiom/yugongyishan.html"}, {"n": "夸父逐日", "p": "kuā fù zhú rì", "m": "比喻人有大志，也比喻不自量力。", "u": "idiom/kuafuzhuri.html"}, {"n": "精卫填海", "p": "jīng wèi tián hǎi", "m": "比喻意志坚决，不畏艰难，为达到目标奋斗不息。", "u": "idiom/jingweitianhai.html"}, {"n": "女娲补天", "p": "nǚ wā bǔ tiān", "m": "形容改造天地的雄伟气魄和大无畏的斗争精神。", "u": "idiom/nuwabutian.html"}, {"n": "盘古开天", "p": "pán gǔ kāi tiān", "m": "指人类开始有了历史，比喻开天辟地的伟大创举。", "u": "idiom/pangukaitian.html"}, {"n": "曹冲称象", "p": "cáo chōng chēng xiàng", "m": "称赞人聪明机智，年纪虽小却善于动脑解决难题。", "u": "idiom/caochongchengxiang.html"}, {"n": "黔驴技穷", "p": "qián lǘ jì qióng", "m": "比喻有限的一点本领也已经用完了。", "u": "idiom/qianlujiqiong.html"}, {"n": "杯弓蛇影", "p": "bēi gōng shé yǐng", "m": "将映在酒杯里的弓影误认为蛇。比喻因疑神疑鬼而引起恐惧。", "u": "idiom/beigongsheying.html"}, {"n": "朝三暮四", "p": "zhāo sān mù sì", "m": "原指玩弄手法欺骗人。后用来比喻常常变卦，反复无常。", "u": "idiom/zhaosanmusi.html"}, {"n": "唇亡齿寒", "p": "chún wáng chǐ hán", "m": "嘴唇没有了，牙齿就会感到寒冷。比喻双方息息相关，荣辱与共。", "u": "idiom/chunwangchihan.html"}, {"n": "城门失火", "p": "chéng mén shī huǒ", "m": "城门着了火，人们用护城河的水救火，水用完了，河里的鱼也干死了。比喻因受连累而遭到", "u": "idiom/chengmenshihuo.html"}, {"n": "前车之鉴", "p": "qián chē zhī jiàn", "m": "前面车子翻倒的教训。比喻先前的失败，可以做为以后的教训。", "u": "idiom/qianchezhijian.html"}, {"n": "他山之石", "p": "tā shān zhī shí", "m": "别的山上的石头，可以用来琢磨玉器。比喻能帮助自己改正缺点的人或意见。常与「可以攻", "u": "idiom/tashanzhishi.html"}, {"n": "千里之堤", "p": "qiān lǐ zhī dī", "m": "千里长的大堤。比喻宏伟的事业或长期的积累。常与「溃于蚁穴」连用，警示小事不慎将酿", "u": "idiom/qianlizhidi.html"}, {"n": "不积跬步", "p": "bù jī kuǐ bù", "m": "不积累一步半步的行程，就没有办法达到千里之远。比喻学习工作贵在不断积累。常与「无", "u": "idiom/bujikuibu.html"}, {"n": "流水不腐", "p": "liú shuǐ bù fǔ", "m": "流动的水不会发臭。比喻经常运动的事物不易受到侵蚀，可以保持活力。常与「户枢不蠹」", "u": "idiom/liushuibufu.html"}, {"n": "近朱者赤", "p": "jìn zhū zhě chì", "m": "靠着朱砂的变红。比喻接近好人可以使人变好，接近坏人可以使人变坏。指客观环境对人有", "u": "idiom/jinzhuzhechi.html"}, {"n": "青出于蓝", "p": "qīng chū yú lán", "m": "靛青是从蓼蓝里提炼出来的，但颜色比蓼蓝更深。比喻学生超过老师或后人胜过前人。常与", "u": "idiom/qingchuyulan.html"}, {"n": "水滴石穿", "p": "shuǐ dī shí chuān", "m": "水不停地滴，石头也能被滴穿。比喻只要有恒心，不断努力，事情就一定能成功。", "u": "idiom/shuidishichuan.html"}, {"n": "风和日丽", "p": "fēng hé rì lì", "m": "和风习习，阳光灿烂。形容晴朗暖和的天气。", "u": "idiom/fengherili.html"}, {"n": "风平浪静", "p": "fēng píng làng jìng", "m": "指没有风浪，水面很平静。比喻平静无事。", "u": "idiom/fengpinglangjing.html"}, {"n": "风雨同舟", "p": "fēng yǔ tóng zhōu", "m": "在狂风暴雨中同乘一条船，一起与风雨搏斗。比喻共同经历患难。", "u": "idiom/fengyutongzhou.html"}, {"n": "风雨交加", "p": "fēng yǔ jiāo jiā", "m": "又是刮风，又是下雨。比喻几种灾难同时袭来。", "u": "idiom/fengyujiaojia.html"}, {"n": "风起云涌", "p": "fēng qǐ yún yǒng", "m": "大风刮起，乌云涌现。比喻新事物相继兴起，声势很盛。", "u": "idiom/fengqiyunyong.html"}, {"n": "风卷残云", "p": "fēng juǎn cán yún", "m": "大风把残云卷走。比喻一下子把残存的东西一扫而光。", "u": "idiom/fengjuancanyun.html"}, {"n": "风调雨顺", "p": "fēng tiáo yǔ shùn", "m": "风雨及时适宜。形容风雨适合农时，年景好。", "u": "idiom/fengtiaoyushun.html"}, {"n": "呼风唤雨", "p": "hū fēng huàn yǔ", "m": "旧指神仙道士的法力。现比喻人具有支配自然的伟大力量，也可形容反动势力猖獗。", "u": "idiom/hufenghuanyu.html"}, {"n": "满城风雨", "p": "mǎn chéng fēng yǔ", "m": "城里到处刮风下雨。原形容重阳节前的雨景。后比喻某一事件传播很广，到处议论纷纷。", "u": "idiom/manchengfengyu.html"}, {"n": "春风化雨", "p": "chūn fēng huà yǔ", "m": "指适宜于草木生长的风雨。比喻良好的熏陶和教育，多用来称颂师长的教诲。", "u": "idiom/chunfenghuayu.html"}, {"n": "未雨绸缪", "p": "wèi yǔ chóu móu", "m": "天还没有下雨，先把门窗绑牢。比喻事先做好准备工作，防患于未然。", "u": "idiom/weiyuchoumou.html"}, {"n": "雨后春笋", "p": "yǔ hòu chūn sǔn", "m": "指春天下雨后，竹笋一下子就长出来很多。比喻事物迅速大量地涌现出来。", "u": "idiom/yuhouchunsun.html"}, {"n": "雨过天晴", "p": "yǔ guò tiān qíng", "m": "雨后转晴。也比喻政治上由黑暗到光明，或情况由坏变好。", "u": "idiom/yuguotianqing.html"}, {"n": "云消雾散", "p": "yún xiāo wù sàn", "m": "像烟云消散一样。比喻事物消失得干干净净。", "u": "idiom/yunxiaowusan.html"}, {"n": "腾云驾雾", "p": "téng yún jià wù", "m": "原是传说中指会法术的人乘云雾飞行。后形容奔驰迅速或头脑发昏。", "u": "idiom/tengyunjiawu.html"}, {"n": "直上云霄", "p": "zhí shàng yún xiāo", "m": "一直冲上天空的云层。形容上升得极高，也比喻志向高远。", "u": "idiom/zhishangyunxiao.html"}, {"n": "过眼云烟", "p": "guò yǎn yún yān", "m": "从眼前飘过的云烟。原比喻身外之物，不必重视。后比喻很快就消失的事物。", "u": "idiom/guoyanyunyan.html"}, {"n": "烟消云散", "p": "yān xiāo yún sàn", "m": "像烟云消散一样。比喻事物消失得干干净净。", "u": "idiom/yanxiaoyunsan.html"}, {"n": "电闪雷鸣", "p": "diàn shǎn léi míng", "m": "闪电飞光，雷声轰鸣。比喻快速有力，也比喻轰轰烈烈。", "u": "idiom/dianshanleiming.html"}, {"n": "雷霆万钧", "p": "léi tíng wàn jūn", "m": "形容威力极大，无法阻挡。", "u": "idiom/leitingwanjun.html"}, {"n": "晴天霹雳", "p": "qíng tiān pī lì", "m": "晴天打响雷。比喻突然发生意外的、令人震惊的事件。", "u": "idiom/qingtianpili.html"}, {"n": "山清水秀", "p": "shān qīng shuǐ xiù", "m": "形容风景优美。", "u": "idiom/shanqingshuixiu.html"}, {"n": "山崩地裂", "p": "shān bēng dì liè", "m": "山岳倒塌，大地裂开。形容响声巨大或变化剧烈。", "u": "idiom/shanbengdilie.html"}, {"n": "山穷水尽", "p": "shān qióng shuǐ jìn", "m": "山和水都到了尽头。比喻无路可走，陷入绝境。", "u": "idiom/shanqiongshuijin.html"}, {"n": "青山绿水", "p": "qīng shān lǜ shuǐ", "m": "泛称美好山河。", "u": "idiom/qingshanlushui.html"}, {"n": "绿水青山", "p": "lǜ shuǐ qīng shān", "m": "泛称美好山河，现多用于强调生态环境优美。", "u": "idiom/lushuiqingshan.html"}, {"n": "崇山峻岭", "p": "chóng shān jùn lǐng", "m": "高大陡峻的山岭。", "u": "idiom/chongshanjunling.html"}, {"n": "翻山越岭", "p": "fān shān yuè lǐng", "m": "翻越不少山头。形容野外工作或旅途的辛苦。", "u": "idiom/fanshanyueling.html"}, {"n": "开门见山", "p": "kāi mén jiàn shān", "m": "打开门就能看见山。比喻说话或写文章直截了当谈本题，不拐弯抹角。", "u": "idiom/kaimenjianshan.html"}, {"n": "排山倒海", "p": "pái shān dǎo hǎi", "m": "推开高山，翻倒大海。形容力量强盛，声势浩大。", "u": "idiom/paishandaohai.html"}, {"n": "冰清玉洁", "p": "bīng qīng yù jié", "m": "像冰那样清澈透明，像玉那样洁白无瑕。比喻人的操行清白。", "u": "idiom/bingqingyujie.html"}, {"n": "冰天雪地", "p": "bīng tiān xuě dì", "m": "形容冰雪漫天盖地，非常寒冷。", "u": "idiom/bingtianxuedi.html"}, {"n": "冰山一角", "p": "bīng shān yī jiǎo", "m": "冰山露出水面的只是一小部分。比喻事物所显露出来的只是很小的一部分，更大的部分还隐", "u": "idiom/bingshanyijiao.html"}, {"n": "火上浇油", "p": "huǒ shàng jiāo yóu", "m": "往火上倒油。比喻使人更加愤怒或使情况更加严重。", "u": "idiom/huoshangjiaoyou.html"}, {"n": "火树银花", "p": "huǒ shù yín huā", "m": "火红的树，指树上挂满灯彩；银白色的花，指灯光雪亮。形容张灯结彩或大放焰火的灿烂夜", "u": "idiom/huoshuyinhua.html"}, {"n": "水深火热", "p": "shuǐ shēn huǒ rè", "m": "老百姓所受的灾难，像水那样越来越深，像火那样越来越热。比喻人民生活极端痛苦。", "u": "idiom/shuishenhuore.html"}, {"n": "星火燎原", "p": "xīng huǒ liáo yuán", "m": "一点儿小火星可以把整个原野烧起来。常比喻新生事物开始时力量虽然很小，但有旺盛的生", "u": "idiom/xinghuoliaoyuan.html"}, {"n": "如花似玉", "p": "rú huā sì yù", "m": "像花和玉那样美好。形容女子姿容出众。", "u": "idiom/ruhuasiyu.html"}, {"n": "花团锦簇", "p": "huā tuán jǐn cù", "m": "形容五彩缤纷、十分鲜艳多彩的景象。也形容文章辞藻华丽。", "u": "idiom/huatuanjincu.html"}, {"n": "闭月羞花", "p": "bì yuè xiū huā", "m": "使月亮躲藏，使花儿羞惭。形容女子容貌美丽。", "u": "idiom/biyuexiuhua.html"}, {"n": "雾里看花", "p": "wù lǐ kàn huā", "m": "原形容年老视力差，看东西模糊。后也比喻看事情不真切。", "u": "idiom/wulikanhua.html"}, {"n": "妙笔生花", "p": "miào bǐ shēng huā", "m": "比喻杰出的写作才能。", "u": "idiom/miaobishenghua.html"}, {"n": "光阴似箭", "p": "guāng yīn sì jiàn", "m": "时间如箭，迅速流逝。形容时间过得极快。", "u": "idiom/guangyinsijian.html"}, {"n": "日月如梭", "p": "rì yuè rú suō", "m": "太阳和月亮像穿梭一样地来去。形容时间过得很快。", "u": "idiom/riyuerusuo.html"}, {"n": "白驹过隙", "p": "bái jū guò xì", "m": "像白色骏马在细小的缝隙前跑过一样。形容时间过得极快。", "u": "idiom/baijuguoxi.html"}, {"n": "争分夺秒", "p": "zhēng fēn duó miǎo", "m": "一分一秒也不放过。形容充分利用时间。", "u": "idiom/zhengfenduomiao.html"}, {"n": "长年累月", "p": "cháng nián lěi yuè", "m": "形容经过了很多年月，时间很长。", "u": "idiom/changnianleiyue.html"}, {"n": "猴年马月", "p": "hóu nián mǎ yuè", "m": "泛指未来的岁月，常指遥遥无期、不知何年何月。", "u": "idiom/hounianmayue.html"}, {"n": "指日可待", "p": "zhǐ rì kě dài", "m": "为期不远，不久就可以实现。", "u": "idiom/zhirikedai.html"}, {"n": "度日如年", "p": "dù rì rú nián", "m": "过一天像过一年那样长。形容日子很不好过。", "u": "idiom/durirunian.html"}, {"n": "沧海桑田", "p": "cāng hǎi sāng tián", "m": "大海变成桑田，桑田变成大海。比喻世事变化很大。", "u": "idiom/canghaisangtian.html"}, {"n": "时不我待", "p": "shí bù wǒ dài", "m": "时间不会等待我们。指要抓紧时间。", "u": "idiom/shibuwodai.html"}, {"n": "百年树人", "p": "bǎi nián shù rén", "m": "比喻培养人才是长期而艰巨的事。常与「十年树木」连用。", "u": "idiom/bainianshuren.html"}];